window.BANK['m7']['m7-1-1'] = [
  {"q":"ما الخطوة الأولى من خطوات حل المسألة؟","o":["خطط","افهم","حُلّ","تحقق"],"a":1,"why":"خطوات حل المسألة أربع بهذا الترتيب: افهم، ثم خطط، ثم حُلّ، ثم تحقق. نبدأ بـ«افهم» لأننا لا نستطيع حل مسألة قبل أن نعرف ماذا تقول وماذا تطلب.","ow":["«خطط» هي الخطوة الثانية، وتأتي بعد أن نفهم المسألة.","","«حُلّ» هي الخطوة الثالثة، ننفذ فيها الخطة.","«تحقق» هي الخطوة الأخيرة وليست الأولى."]},
  {"q":"ما الخطوة الأخيرة من خطوات حل المسألة؟","o":["تحقق","افهم","خطط","حُلّ"],"a":0,"why":"الخطوات الأربع مرتبة: افهم، خطط، حُلّ، ثم تحقق في النهاية. نراجع الإجابة بعد أن ننتهي من الحل لنتأكد أنها معقولة ومناسبة للتقدير.","ow":["","«افهم» هي الخطوة الأولى لا الأخيرة.","«خطط» هي الخطوة الثانية.","«حُلّ» هي الخطوة الثالثة، وبعدها نتحقق."]},
  {"q":"في أي خطوة نسأل: ما المعطيات وما المطلوب؟","o":["خطط","حُلّ","تحقق","افهم"],"a":3,"why":"في خطوة «افهم» نقرأ المسألة ونحدد المعطيات (ما نعرفه) والمطلوب (ما نبحث عنه). هذا السؤال هو سؤال الخطوة الأولى بالذات.","ow":["في «خطط» نختار طريقة الحل، وقد حددنا المعطيات قبلها.","في «حُلّ» ننفذ الخطة ونحسب.","في «تحقق» نراجع الإجابة بعد الحل.",""]},
  {"q":"في أي خطوة نختار خطة مثل جدول أو نمط ونقدّر الإجابة؟","o":["افهم","حُلّ","خطط","تحقق"],"a":2,"why":"في خطوة «خطط» نختار خطة للحل مثل رسم جدول أو إيجاد نمط، ونقدّر الإجابة تقريبًا قبل الحساب. هذا ما يميز الخطوة الثانية.","ow":["«افهم» لتحديد المعطيات والمطلوب فقط.","«حُلّ» لتنفيذ الخطة بعد اختيارها.","","«تحقق» لمراجعة الإجابة في النهاية."]},
  {"q":"في أي خطوة ننفذ الخطة ونحسب خطوة بعد خطوة؟","o":["افهم","حُلّ","خطط","تحقق"],"a":1,"why":"خطوة «حُلّ» هي التي ننفذ فيها الخطة التي اخترناها ونحسب خطوة بعد خطوة. إذا لم تنجح الخطة نغيّرها ونجرب أخرى.","ow":["«افهم» نقرأ فيها المسألة ولا نحسب.","","«خطط» نختار فيها الطريقة قبل أن ننفذها.","«تحقق» نراجع فيها الجواب بعد الانتهاء من الحساب."]},
  {"q":"ما الترتيب الصحيح لخطوات حل المسألة؟","o":["افهم، خطط، حُلّ، تحقق","خطط، افهم، حُلّ، تحقق","حُلّ، افهم، خطط، تحقق","افهم، حُلّ، خطط، تحقق"],"a":0,"why":"الترتيب الصحيح هو افهم ثم خطط ثم حُلّ ثم تحقق. لا يصح أن نحل قبل أن نفهم ونخطط، ولا أن نتحقق قبل أن نجد الإجابة.","ow":["","هنا «خطط» جاءت قبل «افهم»، لكن لا نخطط لمسألة لم نفهمها بعد.","هنا «حُلّ» جاءت في أول الخطوات، والصحيح أن نفهم المسألة أولًا.","هنا «حُلّ» جاءت قبل «خطط»، والصحيح أن نضع الخطة قبل الحل."]},
  {"q":"ما العدد التالي في النمط: 5 ، 10 ، 15 ، 20 ، ... ؟","o":["24","30","35","25"],"a":3,"why":"النمط: 5 ، 10 ، 15 ، 20، والفرق بين كل عددين متتاليين ثابت وهو 5. العدد التالي = 20 + 5 = 25.","ow":["24 لا يزيد بمقدار 5 عن 20 (الفرق 4 فقط).","30 هو العدد الذي بعد 25، أي نتخطى عددًا واحدًا.","35 يتخطى عددين، والمطلوب العدد التالي مباشرة.",""]},
  {"q":"ما العدد التالي في النمط: 2 ، 4 ، 8 ، 16 ، ... ؟","o":["24","30","32","20"],"a":2,"why":"كل عدد في النمط 2 ، 4 ، 8 ، 16 يساوي العدد السابق مضروبًا في 2، فالتالي 16 × 2 = 32.","ow":["24 يأتي من جمع 8 لا من الضرب في 2.","30 لا يتبع النمط، فـ 16 × 2 لا يساوي 30.","","20 هو 16 + 4، والنمط يعتمد على الضرب في 2 لا على جمع 4."]},
  {"q":"ما العدد التالي في النمط: 1 ، 4 ، 9 ، 16 ، ... ؟","o":["20","25","24","36"],"a":1,"why":"نحسب الفروق في النمط 1 ، 4 ، 9 ، 16: 3 ثم 5 ثم 7، أي تزيد 2 في كل مرة، فالفرق التالي 9. العدد التالي = 16 + 9 = 25 (وهي مربعات الأعداد 1 و2 و3 و4 و5).","ow":["20 يعني أن الفرق 4 فقط، لكن الفرق الصحيح 9.","","24 يعني أن الفرق 8، والنمط يعطي فرقًا فرديًا هو 9.","36 هو 6 × 6، ويتخطى العدد 25."]},
  {"q":"ما العدد التالي في النمط: 3 ، 6 ، 12 ، 24 ، ... ؟","o":["48","36","30","27"],"a":0,"why":"النمط 3 ، 6 ، 12 ، 24: كل عدد ضعف السابق، أي نضرب في 2. فالتالي 24 × 2 = 48. تذكّر: خطوات حل المسألة أربع بالترتيب: افهم، خطط، حُلّ، تحقق، ونتحقق في النهاية من معقولية الإجابة.","ow":["","36 هو 24 + 12، وهذا لا يطابق قاعدة الضرب في 2.","30 هو 24 + 6، والنمط ليس جمعًا ثابتًا.","27 هو 24 + 3، لا يتبع النمط (الأعداد تتضاعف)."]},
  {"q":"عدد أقطار المضلع: ثلاثي 0 ، رباعي 2 ، خماسي 5 ، سداسي 9. كم قطرًا للمضلع الخماسي؟","o":["2","9","14","5"],"a":3,"why":"من جدول النمط: المضلع الثلاثي 0 قطر، الرباعي 2، الخماسي 5، السداسي 9. المضلع الخماسي له 5 أقطار كما في الجدول (الفروق 2 ثم 3 ثم 4).","ow":["2 هو عدد أقطار المضلع الرباعي.","9 هو عدد أقطار المضلع السداسي.","14 هو عدد أقطار المضلع السباعي، والسؤال عن الخماسي.",""]},
  {"q":"ما العدد المثلثي التالي بعد: 1 ، 3 ، 6 ، 10 ، 15 ، 21 ؟","o":["27","26","28","30"],"a":2,"why":"الأعداد المثلثية تزيد بمقدار 2 ثم 3 ثم 4 ثم 5 ثم 6، فالتالي نضيف 7: 21 + 7 = 28.","ow":["27 يعني إضافة 6 فقط، لكن المطلوب إضافة 7.","26 يعني إضافة 5، وهذا فرق سابق.","","30 يعني إضافة 9، ولا يتبع النمط."]},
  {"q":"طلب العالم على النفط 100 مليون برميل ويزيد 2 مليون كل سنة. كم يصبح بعد 5 سنوات؟","o":["105 مليون","110 مليون","102 مليون","120 مليون"],"a":1,"why":"الطلب يزيد 2 مليون كل سنة، فخلال 5 سنوات تكون الزيادة 5 × 2 = 10 مليون. الطلب بعد 5 سنوات = 100 + 10 = 110 مليون برميل.","ow":["105 مليون تعني أن الزيادة 5 مليون فقط، أي نسينا ضرب 5 × 2.","","102 مليون هي زيادة سنة واحدة فقط.","120 مليون تعني زيادة 20، أي أننا ضاعفنا الزيادة خطأً."]},
  {"q":"يحرك طائر جناحيه 50 مرة في الثانية. كم مرة يحركهما في 10 ثوانٍ؟","o":["500","60","5000","150"],"a":0,"why":"الطائر يحرك جناحيه 50 مرة في الثانية، فنضرب في عدد الثواني: 50 × 10 = 500 مرة. تذكّر: خطوات حل المسألة أربع بالترتيب: افهم، خطط، حُلّ، تحقق، ونتحقق في النهاية من معقولية الإجابة.","ow":["","60 هو ناتج 50 + 10، والمطلوب ضرب لا جمع.","5000 يعني أننا ضربنا في 100 بدل 10.","150 لا يعبر عن أي عملية صحيحة، فالضرب يعطي 500."]},
  {"q":"دفع كل طالب 6 ريالات للمواصلات. كم دفع 10 طلاب؟","o":["16 ريالًا","600 ريال","66 ريالًا","60 ريالًا"],"a":3,"why":"لكل طالب 6 ريالات، فنضرب عدد الطلاب في المبلغ: 10 × 6 = 60 ريالًا. تذكّر: خطوات حل المسألة أربع بالترتيب: افهم، خطط، حُلّ، تحقق، ونتحقق في النهاية من معقولية الإجابة.","ow":["16 ريالًا ناتج جمع 10 + 6، والمطلوب ضرب.","600 ريال تعني أننا ضربنا في 100 بدل 10.","66 ريالًا لا يعبر عن 10 × 6 (الناتج 60).",""]},
  {"q":"الخطوة الأولى في حل المسألة هي «حُلّ».","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالخطوة الأولى هي «افهم» وليست «حُلّ». «حُلّ» هي الخطوة الثالثة بعد افهم وخطط.","ow":["«صح» تعني أن الحل يأتي أولًا، لكن الترتيب الصحيح يبدأ بـ«افهم».",""]},
  {"q":"إذا لم تنجح الخطة نختار خطة أخرى.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالكتاب ينص في خطوة «حُلّ» على أنه إذا لم تنجح الخطة نختار خطة أخرى. فالمحاولة الأولى قد لا تنجح ولا مشكلة في التغيير.","ow":["","«خطأ» غير صحيحة، فتغيير الخطة جزء من الحل."]},
  {"q":"نقارن الإجابة بالتقدير في خطوة «تحقق».","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، ففي خطوة «تحقق» نراجع الإجابة ونقارنها بالتقدير الذي وضعناه في خطوة «خطط»، لنعرف إن كانت معقولة.","ow":["","«خطأ» غير صحيحة، فالمقارنة بالتقدير جزء من خطوة تحقق."]},
  {"q":"العدد التالي في النمط 2 ، 4 ، 6 ، 8 هو 9.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، لأن النمط 2 ، 4 ، 6 ، 8 يزيد 2 في كل مرة، فالتالي 8 + 2 = 10 وليس 9.","ow":["«صح» تعني أن التالي 9، لكن الفرق ثابت 2 فيكون التالي 10.",""]},
  {"q":"الأعداد 1 ، 3 ، 6 ، 10 ، 15 تسمى أعدادًا مثلثية.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالأعداد 1 ، 3 ، 6 ، 10 ، 15 تزيد بمقدار 2 ثم 3 ثم 4 ثم 5، وتسمى الأعداد المثلثية لأنها تشكل نقاطًا على شكل مثلث.","ow":["","«خطأ» غير صحيحة، فهذا هو النمط المعروف للأعداد المثلثية."]}
];
window.BANK['m7']['m7-1-2'] = [
  {"q":"ما الأساس في القوة 8<sup>3</sup> ؟","o":["3","24","8","11"],"a":2,"why":"في القوة 8<sup>3</sup> العدد الكبير 8 هو الأساس، وهو العدد الذي يتكرر في الضرب، والرقم الصغير 3 هو الأس. أي أن 8 × 8 × 8.","ow":["3 هو الأس وليس الأساس.","24 ناتج 8 × 3، وهذا ليس معنى القوة.","","11 ناتج 8 + 3، والقوة لا تعني جمعًا."]},
  {"q":"ما الأس في القوة 9<sup>5</sup> ؟","o":["9","5","45","14"],"a":1,"why":"في القوة 9<sup>5</sup> الرقم الصغير المرفوع 5 هو الأس، وهو يدل على عدد مرات تكرار الأساس 9 في الضرب.","ow":["9 هو الأساس لا الأس.","","45 ناتج 9 × 5، والأس لا يُضرب في الأساس.","14 ناتج 9 + 5، وهذا ليس الأس."]},
  {"q":"اكتب بالصيغة الأسية: 5 × 5 × 5","o":["5<sup>3</sup>","3<sup>5</sup>","5<sup>2</sup>","15"],"a":0,"why":"العدد 5 تكرر في الضرب 3 مرات، فنكتب الأساس 5 والأس 3: 5<sup>3</sup>. عدد مرات التكرار يكون هو الأس.","ow":["","3<sup>5</sup> تعني 3 مضروبة 5 مرات، وقد عكسنا الأساس والأس.","5<sup>2</sup> تعني 5 × 5 فقط، لكن 5 تكررت 3 مرات.","15 ناتج 5 × 3 وليس صيغة أسية."]},
  {"q":"اكتب بالصيغة الأسية: 2 × 2 × 2 × 2 × 2 × 2","o":["6<sup>2</sup>","2<sup>5</sup>","12","2<sup>6</sup>"],"a":3,"why":"العدد 2 يظهر في الضرب 6 مرات، فنكتب 2<sup>6</sup>: الأساس 2 والأس 6 (نعدّ العوامل: 2 × 2 × 2 × 2 × 2 × 2).","ow":["6<sup>2</sup> تعني 6 × 6، وقد عكسنا الأساس والأس.","2<sup>5</sup> تعني 5 مرات فقط، والصحيح 6 مرات.","12 ناتج 2 × 6، وليس القوة.",""]},
  {"q":"ما قيمة 3<sup>2</sup> ؟","o":["6","8","9","5"],"a":2,"why":"3<sup>2</sup> تعني أن نضرب 3 في نفسه مرتين: 3 × 3 = 9. تذكّر: في القوة أس يدل على عدد مرات ضرب الأساس في نفسه، مثل 3<sup>4</sup> = 3 × 3 × 3 × 3.","ow":["6 هو 3 × 2 وليس 3 × 3.","8 هو 2<sup>3</sup> وليس 3<sup>2</sup>.","","5 هو 3 + 2، والقوة ضرب لا جمع."]},
  {"q":"ما قيمة 5<sup>2</sup> ؟","o":["10","25","7","52"],"a":1,"why":"5<sup>2</sup> تعني 5 × 5 = 25 (نضرب الأساس في نفسه بعدد مرات الأس). تذكّر: في القوة أس يدل على عدد مرات ضرب الأساس في نفسه، مثل 3<sup>4</sup> = 3 × 3 × 3 × 3.","ow":["10 هو 5 × 2، أي ضربنا الأساس في الأس.","","7 هو 5 + 2، وهذا ليس معنى القوة.","52 مجرد كتابة الرقمين بجوار بعض."]},
  {"q":"ما قيمة 2<sup>3</sup> ؟","o":["8","6","9","5"],"a":0,"why":"2<sup>3</sup> تعني 2 × 2 × 2: أولًا 2 × 2 = 4 ثم 4 × 2 = 8. تذكّر: في القوة أس يدل على عدد مرات ضرب الأساس في نفسه، مثل 3<sup>4</sup> = 3 × 3 × 3 × 3.","ow":["","6 هو 2 × 3 وليس 2 × 2 × 2.","9 هو 3<sup>2</sup> وليس 2<sup>3</sup>.","5 هو 2 + 3، والقوة تعني ضربًا."]},
  {"q":"ما قيمة 10<sup>3</sup> ؟","o":["30","100","10000","1000"],"a":3,"why":"10<sup>3</sup> تعني 10 × 10 × 10: 10 × 10 = 100 ثم 100 × 10 = 1000. الأس 3 يعني ثلاثة أصفار بعد الواحد.","ow":["30 هو 10 × 3، أي ضربنا الأساس في الأس.","100 هي 10<sup>2</sup> وليس 10<sup>3</sup>.","10000 هي 10<sup>4</sup>، بأربعة أصفار.",""]},
  {"q":"ما قيمة 2<sup>6</sup> ؟","o":["12","32","64","128"],"a":2,"why":"2<sup>6</sup> تعني ضرب 2 ست مرات: 2 ثم 4 ثم 8 ثم 16 ثم 32 ثم 64. تذكّر: في القوة أس يدل على عدد مرات ضرب الأساس في نفسه، مثل 3<sup>4</sup> = 3 × 3 × 3 × 3.","ow":["12 هو 2 × 6 وليس القوة.","32 هو 2<sup>5</sup>، أي خمس مرات فقط.","","128 هو 2<sup>7</sup>، أي سبع مرات."]},
  {"q":"ما قيمة 3<sup>4</sup> ؟","o":["12","81","64","27"],"a":1,"why":"3<sup>4</sup> تعني ضرب 3 أربع مرات: 3 × 3 = 9 ثم 9 × 3 = 27 ثم 27 × 3 = 81. تذكّر: في القوة أس يدل على عدد مرات ضرب الأساس في نفسه، مثل 3<sup>4</sup> = 3 × 3 × 3 × 3.","ow":["12 هو 3 × 4 وليس القوة.","","64 هو 4<sup>3</sup> أو 2<sup>6</sup>، وليس 3<sup>4</sup>.","27 هو 3<sup>3</sup>، أي ثلاث مرات فقط."]},
  {"q":"ما قيمة 6<sup>2</sup> ؟","o":["36","12","26","66"],"a":0,"why":"6<sup>2</sup> تعني 6 × 6 = 36. تذكّر: في القوة أس يدل على عدد مرات ضرب الأساس في نفسه، مثل 3<sup>4</sup> = 3 × 3 × 3 × 3.","ow":["","12 هو 6 × 2 وليس 6 × 6.","26 مجرد كتابة الرقمين، وليس الناتج.","66 مجرد تكرار الرقم، وليس الضرب."]},
  {"q":"كيف تُقرأ القوة 5<sup>2</sup> ؟","o":["خمسة تكعيب","اثنان مرفوعًا للقوة الخامسة","خمسة في اثنين","خمسة تربيع"],"a":3,"why":"القوة 5<sup>2</sup> أسّها 2، والأس 2 يُقرأ «تربيع»، فتُقرأ: خمسة تربيع. تذكّر: في القوة أس يدل على عدد مرات ضرب الأساس في نفسه، مثل 3<sup>4</sup> = 3 × 3 × 3 × 3.","ow":["الأس 3 هو الذي يُقرأ تكعيب، وهنا الأس 2.","هذه القراءة تعكس الأساس والأس.","«خمسة في اثنين» تعني ضربًا عاديًا 5 × 2 وليس قوة.",""]},
  {"q":"كيف تُقرأ القوة 4<sup>3</sup> ؟","o":["أربعة تربيع","ثلاثة تكعيب","أربعة تكعيب","اثنا عشر"],"a":2,"why":"القوة 4<sup>3</sup> أسّها 3، والأس 3 يُقرأ «تكعيب»، فتُقرأ: أربعة تكعيب. تذكّر: في القوة أس يدل على عدد مرات ضرب الأساس في نفسه، مثل 3<sup>4</sup> = 3 × 3 × 3 × 3.","ow":["«تربيع» للأس 2 لا للأس 3.","هذه قراءة 3<sup>4</sup> وليس 4<sup>3</sup>.","","12 هو ناتج 4 × 3 وليس قراءة للقوة."]},
  {"q":"ما قيمة 1<sup>8</sup> ؟","o":["8","1","0","18"],"a":1,"why":"الواحد مضروبًا في نفسه أي عدد من المرات يبقى 1: 1 × 1 × ... × 1 = 1. فـ 1<sup>8</sup> = 1. تذكّر: في القوة أس يدل على عدد مرات ضرب الأساس في نفسه، مثل 3<sup>4</sup> = 3 × 3 × 3 × 3.","ow":["8 هو الأس وليس القيمة.","","0 غير صحيح، فالضرب في 1 لا يعطي صفرًا.","18 مجرد كتابة الرقمين بجوار بعض."]},
  {"q":"ما قيمة 5<sup>3</sup> ؟","o":["125","15","35","75"],"a":0,"why":"5<sup>3</sup> = 5 × 5 × 5: أولًا 5 × 5 = 25 ثم 25 × 5 = 125. تذكّر: في القوة أس يدل على عدد مرات ضرب الأساس في نفسه، مثل 3<sup>4</sup> = 3 × 3 × 3 × 3.","ow":["","15 هو 5 × 3 وليس القوة.","35 هو 5 + 5 + ... أو كتابة الرقمين، وليس الناتج.","75 هو 25 × 3 أي ضربنا في الأس بدل الأساس."]},
  {"q":"7<sup>3</sup> تساوي 7 × 3.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، لأن 7<sup>3</sup> معناها 7 × 7 × 7 = 343 وليست 7 × 3 = 21. الأس يدل على عدد مرات تكرار الأساس.","ow":["«صح» تعني أن الأس يُضرب في الأساس، لكنه يدل على تكرار الأساس.",""]},
  {"q":"2<sup>3</sup> = 8","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، لأن 2<sup>3</sup> = 2 × 2 × 2 = 4 × 2 = 8. تذكّر: في القوة أس يدل على عدد مرات ضرب الأساس في نفسه، مثل 3<sup>4</sup> = 3 × 3 × 3 × 3.","ow":["","«خطأ» غير صحيحة، فالناتج فعلًا 8."]},
  {"q":"الأس يدل على عدد مرات تكرار الأساس في الضرب.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالأس هو الرقم الصغير الذي يدل على عدد المرات التي نكتب فيها الأساس ونضربه في نفسه، مثل 5<sup>3</sup> = 5 × 5 × 5.","ow":["","«خطأ» غير صحيحة، فهذا هو تعريف الأس."]},
  {"q":"4<sup>2</sup> = 8","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فـ 4<sup>2</sup> = 4 × 4 = 16 وليس 8. الرقم 8 هو 4 × 2 وهذا ضرب الأساس في الأس.","ow":["«صح» تعني أن 4<sup>2</sup> = 8، لكن الناتج 16.",""]},
  {"q":"1<sup>100</sup> = 1","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، لأن 1 مضروبًا في نفسه 100 مرة يبقى 1 مهما كان عدد المرات. تذكّر: في القوة أس يدل على عدد مرات ضرب الأساس في نفسه، مثل 3<sup>4</sup> = 3 × 3 × 3 × 3.","ow":["","«خطأ» غير صحيحة، فأي قوة للعدد 1 تساوي 1."]}
];
window.BANK['m7']['m7-1-3'] = [
  {"q":"ما العملية التي نحسبها أولًا في: 7 + 3 × 4 ؟","o":["7 + 3","الجمع","لا فرق","3 × 4"],"a":3,"why":"في ترتيب العمليات نحسب الضرب قبل الجمع، فنحسب 3 × 4 أولًا ثم نضيف 7. لذلك 3 × 4 هي أول عملية.","ow":["لو بدأنا بـ 7 + 3 لخالفنا الترتيب، فالضرب أولًا.","الجمع يأتي بعد الضرب، وليس قبله.","يوجد فرق، فالنتيجة تتغير حسب العملية التي نبدأ بها.",""]},
  {"q":"احسب: 7 + 3 × 4","o":["40","24","19","13"],"a":2,"why":"7 + 3 × 4: الضرب أولًا، 3 × 4 = 12. ثم الجمع: 7 + 12 = 19. تذكّر: ترتيب العمليات: الأقواس أولًا، ثم القوى، ثم الضرب والقسمة من اليسار، ثم الجمع والطرح من اليسار.","ow":["40 هو (7 + 3) × 4 أي جمعنا قبل الضرب.","24 غير صحيح، فـ 7 + 12 = 19 وليس 24.","","13 لا يساوي 7 + 12، فالناتج الصحيح 19."]},
  {"q":"احسب: (7 + 3) × 4","o":["19","40","28","19.5"],"a":1,"why":"(7 + 3) × 4: القوس أولًا، 7 + 3 = 10. ثم نضرب: 10 × 4 = 40. تذكّر: ترتيب العمليات: الأقواس أولًا، ثم القوى، ثم الضرب والقسمة من اليسار، ثم الجمع والطرح من اليسار.","ow":["19 ناتج 7 + 3 × 4 بدون قوس، لكن هنا القوس يغيّر الترتيب.","","28 ناتج 7 × 4 فقط، وقد أهملنا الجمع داخل القوس.","19.5 رقم غير مرتبط بالعملية، والناتج الصحيح 40."]},
  {"q":"احسب: 20 − 4 × 3","o":["8","48","12","16"],"a":0,"why":"20 − 4 × 3: الضرب قبل الطرح، 4 × 3 = 12. ثم 20 − 12 = 8. تذكّر: ترتيب العمليات: الأقواس أولًا، ثم القوى، ثم الضرب والقسمة من اليسار، ثم الجمع والطرح من اليسار.","ow":["","48 ناتج (20 − 4) × 3 أي طرحنا قبل الضرب.","12 هو ناتج الضرب فقط، ونسينا الطرح من 20.","16 هو 20 − 4 فقط، ونسينا الضرب في 3."]},
  {"q":"احسب: 18 ÷ 3 + 2","o":["3","4","12","8"],"a":3,"why":"18 ÷ 3 + 2: القسمة قبل الجمع، 18 ÷ 3 = 6. ثم 6 + 2 = 8. تذكّر: ترتيب العمليات: الأقواس أولًا، ثم القوى، ثم الضرب والقسمة من اليسار، ثم الجمع والطرح من اليسار.","ow":["3 غير صحيح، فبعد القسمة لا نتوقف بل نضيف 2.","4 ناتج 18 ÷ (3 + 2) تقريبًا، والصحيح قسمة 18 على 3 فقط.","12 غير صحيح؛ لا يطابق أي خطوة، فالناتج 8.",""]},
  {"q":"احسب: 2 × 3<sup>2</sup>","o":["36","12","18","9"],"a":2,"why":"2 × 3<sup>2</sup>: القوة أولًا، 3<sup>2</sup> = 9. ثم الضرب: 2 × 9 = 18. تذكّر: ترتيب العمليات: الأقواس أولًا، ثم القوى، ثم الضرب والقسمة من اليسار، ثم الجمع والطرح من اليسار.","ow":["36 ناتج (2 × 3)<sup>2</sup> أي ضربنا قبل القوة.","12 هو 2 × 3 × 2 أي ضربنا الأساس في الأس.","","9 هو 3<sup>2</sup> فقط، ونسينا الضرب في 2."]},
  {"q":"احسب: (12 − 4) ÷ 2","o":["10","4","6","2"],"a":1,"why":"(12 − 4) ÷ 2: القوس أولًا، 12 − 4 = 8. ثم 8 ÷ 2 = 4. تذكّر: ترتيب العمليات: الأقواس أولًا، ثم القوى، ثم الضرب والقسمة من اليسار، ثم الجمع والطرح من اليسار.","ow":["10 ناتج 12 − 4 ÷ 2 بدون قوس (12 − 2 = 10).","","6 هو 12 ÷ 2 فقط، وأهملنا الطرح.","2 هو 4 ÷ 2 أي طرحنا 4 ثم قسمنا مرتين."]},
  {"q":"احسب: 5 + 2 × 3<sup>2</sup> − 1","o":["22","62","30","14"],"a":0,"why":"5 + 2 × 3<sup>2</sup> − 1: القوة أولًا 3<sup>2</sup> = 9، ثم الضرب 2 × 9 = 18، ثم من اليسار 5 + 18 = 23 ثم 23 − 1 = 22.","ow":["","62 ليس الناتج، فبعد القوة والضرب 5 + 18 − 1 = 22.","30 ليس الناتج، فالقوة 3<sup>2</sup> = 9 وليست 6 ثم الناتج 22.","14 ليس الناتج، فالقوة والضرب يعطيان 18 ثم 5 + 18 − 1 = 22."]},
  {"q":"احسب: 30 ÷ 5 × 2","o":["3","15","60","12"],"a":3,"why":"30 ÷ 5 × 2: القسمة والضرب بنفس المستوى فنحسب من اليسار إلى اليمين. 30 ÷ 5 = 6 ثم 6 × 2 = 12.","ow":["3 هو 30 ÷ (5 × 2) أي ضربنا أولًا بدل الترتيب من اليسار.","15 هو 30 ÷ 2، وأهملنا الضرب.","60 هو 30 × 2 فقط، وأهملنا القسمة على 5.",""]},
  {"q":"احسب: 9 + 3(4 − 1)","o":["36","21","18","12"],"a":2,"why":"9 + 3(4 − 1): القوس أولًا، 4 − 1 = 3. ثم الضرب 3 × 3 = 9. ثم الجمع 9 + 9 = 18. تذكّر: ترتيب العمليات: الأقواس أولًا، ثم القوى، ثم الضرب والقسمة من اليسار، ثم الجمع والطرح من اليسار.","ow":["36 ناتج (9 + 3) × (4 − 1)، أي جمعنا قبل الضرب.","21 غير صحيح؛ ناتج 9 + 3 × 4 − ... ولا يتبع القوس.","","12 هو 9 + 3، وأهملنا الضرب والقوس."]},
  {"q":"ما العملية التي تأتي مباشرة بعد ما داخل الأقواس في ترتيب العمليات؟","o":["الجمع","القوى","الطرح","القسمة"],"a":1,"why":"ترتيب العمليات: أولًا ما داخل الأقواس، ثم القوى، ثم الضرب والقسمة من اليسار، ثم الجمع والطرح من اليسار. فالقوى تأتي مباشرة بعد الأقواس.","ow":["الجمع يأتي في آخر الترتيب.","","الطرح يأتي في آخر الترتيب مع الجمع.","القسمة تأتي بعد القوى مع الضرب."]},
  {"q":"احسب: 36 ÷ (2 + 4)","o":["6","20","14","3"],"a":0,"why":"36 ÷ (2 + 4): القوس أولًا، 2 + 4 = 6. ثم 36 ÷ 6 = 6. تذكّر: ترتيب العمليات: الأقواس أولًا، ثم القوى، ثم الضرب والقسمة من اليسار، ثم الجمع والطرح من اليسار.","ow":["","20 غير صحيح، فهو لا ينتج من أي خطوة صحيحة.","14 غير صحيح؛ لا يطابق (2 + 4)، فالقوس يساوي 6.","3 هو 36 ÷ 12 أي استخدمنا 12 بدل 6."]},
  {"q":"احسب: 4 × 5 + 2 × 6","o":["66","52","120","32"],"a":3,"why":"4 × 5 + 2 × 6: نحسب الضربين أولًا: 4 × 5 = 20 و 2 × 6 = 12. ثم نجمع: 20 + 12 = 32.","ow":["66 غير صحيح؛ جمعنا قبل الضرب بترتيب خاطئ.","52 هو 20 + 2 × ... وليس الترتيب الصحيح.","120 هو (4 × 5 + 2) × 6 أي أخطأنا في الترتيب.",""]},
  {"q":"احسب: 100 − 10 × 3<sup>2</sup>","o":["810","70","10","100"],"a":2,"why":"100 − 10 × 3<sup>2</sup>: القوة أولًا 3<sup>2</sup> = 9، ثم الضرب 10 × 9 = 90، ثم الطرح 100 − 90 = 10.","ow":["810 هو (100 − 10) × 9 أي طرحنا قبل الضرب.","70 هو 100 − 10 × 3 = 70 أي نسينا القوة.","","100 هو الناتج لو لم نطرح شيئًا، وهذا غير صحيح."]},
  {"q":"اشترت هدى 2 كتب بسعر 12 ريالًا للكتاب و 3 دفاتر بسعر 5 ريالات للدفتر. كم دفعت؟","o":["29 ريالًا","39 ريالًا","75 ريالًا","27 ريالًا"],"a":1,"why":"ثمن الكتب: 2 × 12 = 24 ريالًا، وثمن الدفاتر: 3 × 5 = 15 ريالًا. المجموع 24 + 15 = 39 ريالًا. (الضرب أولًا ثم الجمع.)","ow":["29 غير صحيح؛ قد يحدث بجمع غير مناسب بدل الضرب.","","75 هو (2 + 3) × 15 أي جمعنا قبل الضرب.","27 غير صحيح، فالمجموع الصحيح 39 ريالًا."]},
  {"q":"6 + 4 × 3 = 30","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالضرب قبل الجمع: 4 × 3 = 12 ثم 6 + 12 = 18 وليس 30. الرقم 30 يخرج لو جمعنا أولًا (6 + 4) × 3.","ow":["«صح» تعني أن الجمع يُحسب أولًا، والترتيب الصحيح يبدأ بالضرب.",""]},
  {"q":"8 − 2 × 3 = 2","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالضرب أولًا: 2 × 3 = 6، ثم 8 − 6 = 2. تذكّر: ترتيب العمليات: الأقواس أولًا، ثم القوى، ثم الضرب والقسمة من اليسار، ثم الجمع والطرح من اليسار.","ow":["","«خطأ» غير صحيحة، فالناتج فعلًا 2."]},
  {"q":"2 + 3<sup>2</sup> = 11","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالقوة أولًا: 3<sup>2</sup> = 9، ثم 2 + 9 = 11. تذكّر: ترتيب العمليات: الأقواس أولًا، ثم القوى، ثم الضرب والقسمة من اليسار، ثم الجمع والطرح من اليسار.","ow":["","«خطأ» غير صحيحة، فالناتج فعلًا 11."]},
  {"q":"24 ÷ 4 × 2 = 3","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالقسمة والضرب نحسبهما من اليسار: 24 ÷ 4 = 6 ثم 6 × 2 = 12 وليس 3. تذكّر: ترتيب العمليات: الأقواس أولًا، ثم القوى، ثم الضرب والقسمة من اليسار، ثم الجمع والطرح من اليسار.","ow":["«صح» تعني أننا نضرب 4 × 2 أولًا، لكن نحسب من اليسار فيكون الناتج 12.",""]},
  {"q":"نبدأ دائمًا بحساب ما داخل الأقواس.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالأقواس هي أول ما نحسبه في ترتيب العمليات، ثم القوى ثم الضرب والقسمة ثم الجمع والطرح.","ow":["","«خطأ» غير صحيحة، فالأقواس لها الأولوية دائمًا."]}
];
window.BANK['m7']['m7-1-4'] = [
  {"q":"خمّن عددين مجموعهما 10 وفرقهما 2.","o":["6 و 4","7 و 3","5 و 5","8 و 2"],"a":0,"why":"نختبر الخمسة: 6 + 4 = 10 فالمجموع صحيح، و 6 − 4 = 2 فالفرق صحيح. إذن العددان 6 و 4 يحققان الشرطين معًا.","ow":["","7 + 3 = 10 صحيح، لكن الفرق 7 − 3 = 4 وليس 2.","5 + 5 = 10 صحيح، لكن الفرق 0 وليس 2.","8 + 2 = 10 صحيح، لكن الفرق 6 وليس 2."]},
  {"q":"عددان مجموعهما 12 وحاصل ضربهما 35. ما العددان؟","o":["4 و 8","6 و 6","3 و 9","5 و 7"],"a":3,"why":"نخمّن ونتحقق: 5 + 7 = 12 والمجموع صحيح، و 5 × 7 = 35 وحاصل الضرب صحيح أيضًا. فالعددان 5 و 7.","ow":["4 + 8 = 12 لكن 4 × 8 = 32 وليس 35.","6 + 6 = 12 لكن 6 × 6 = 36 وليس 35.","3 + 9 = 12 لكن 3 × 9 = 27 وليس 35.",""]},
  {"q":"ما العدد الذي إذا ضُرب في 4 ثم أُضيف إلى الناتج 3 كان الناتج 31؟","o":["6","8","7","9"],"a":2,"why":"نخمّن 7: 7 × 4 = 28 ثم 28 + 3 = 31 وهو المطلوب. فالعدد 7. ويمكن العمل بالعكس: 31 − 3 = 28 و 28 ÷ 4 = 7.","ow":["6 × 4 + 3 = 27 وليس 31.","8 × 4 + 3 = 35 وهو أكبر من 31.","","9 × 4 + 3 = 39 وهو أكبر من 31."]},
  {"q":"ما العدد الذي إذا ضُرب في 5 ثم طُرح من الناتج 2 كان الناتج 28؟","o":["5","6","7","8"],"a":1,"why":"نخمّن 6: 6 × 5 = 30 ثم 30 − 2 = 28 وهو المطلوب. فالعدد 6. بالعكس: 28 + 2 = 30 و 30 ÷ 5 = 6.","ow":["5 × 5 − 2 = 23 وليس 28.","","7 × 5 − 2 = 33 وهو أكبر من 28.","8 × 5 − 2 = 38 وهو أكبر من 28."]},
  {"q":"إذا كان ناتج التخمين أقل من المطلوب فماذا نفعل؟","o":["نعدّل التخمين ونزيد القيم","نتوقف","نقلل القيم","نحذف المعطيات"],"a":0,"why":"إذا كان الناتج أقل من المطلوب فهذا يعني أن تخميننا صغير، فنعدّله ونزيد القيم ثم نتحقق مرة أخرى. هكذا تعمل استراتيجية التخمين والتحقق.","ow":["","لا نتوقف لأن الناتج لم يصل إلى المطلوب بعد.","تقليل القيم يبعدنا أكثر عن المطلوب لأن الناتج صغير أصلًا.","لا نحذف المعطيات فهي جزء من المسألة."]},
  {"q":"مع هند 8 أوراق نقدية من فئتي 5 و 10 ريالات قيمتها 55 ريالًا. كم ورقة من فئة 10؟","o":["2","4","5","3"],"a":3,"why":"نخمّن 3 أوراق من فئة 10: يكون معنا 5 أوراق من فئة 5. القيمة 3 × 10 + 5 × 5 = 30 + 25 = 55 وعدد الأوراق 3 + 5 = 8، وهما الشرطان.","ow":["2 ورقة من فئة 10 تعطي 20 + 6 × 5 = 50 وليس 55.","4 أوراق من فئة 10 تعطي 40 + 4 × 5 = 60 وليس 55.","5 أوراق من فئة 10 تعطي 50 + 3 × 5 = 65 وليس 55.",""]},
  {"q":"عددان مجموعهما 15 وفرقهما 3. ما العددان؟","o":["10 و 5","8 و 7","9 و 6","11 و 4"],"a":2,"why":"نخمّن 9 و 6: 9 + 6 = 15 والمجموع صحيح، و 9 − 6 = 3 والفرق صحيح. تذكّر: في التخمين والتحقق نخمّن، ونتحقق بالتعويض في شروط المسألة، ثم نعدّل التخمين حتى نصل للحل الصحيح.","ow":["10 + 5 = 15 لكن الفرق 5 وليس 3.","8 + 7 = 15 لكن الفرق 1 وليس 3.","","11 + 4 = 15 لكن الفرق 7 وليس 3."]},
  {"q":"عددان مجموعهما 20 وحاصل ضربهما 99. ما العددان؟","o":["8 و 12","9 و 11","10 و 10","7 و 13"],"a":1,"why":"نخمّن 9 و 11: 9 + 11 = 20 والمجموع صحيح، و 9 × 11 = 99 والضرب صحيح. تذكّر: في التخمين والتحقق نخمّن، ونتحقق بالتعويض في شروط المسألة، ثم نعدّل التخمين حتى نصل للحل الصحيح.","ow":["8 + 12 = 20 لكن 8 × 12 = 96 وليس 99.","","10 + 10 = 20 لكن 10 × 10 = 100 وليس 99.","7 + 13 = 20 لكن 7 × 13 = 91 وليس 99."]},
  {"q":"ما العدد الذي إذا ضُرب في 7 ثم أُضيف 2 كان الناتج 51؟","o":["7","6","8","5"],"a":0,"why":"نخمّن 7: 7 × 7 = 49 ثم 49 + 2 = 51 وهو المطلوب. بالعكس: 51 − 2 = 49 و 49 ÷ 7 = 7.","ow":["","6 × 7 + 2 = 44 وليس 51 (والعدد 6 غير مناسب).","8 × 7 + 2 = 58 وهو أكبر من 51.","5 × 7 + 2 = 37 وهو أقل من 51."]},
  {"q":"تضع سلمى 4 تمرات و 2 قطع حلوى في كل طبق. معها 20 تمرة و 10 قطع حلوى. كم طبقًا تملأ؟","o":["4","6","10","5"],"a":3,"why":"سلمى تضع 4 تمرات في كل طبق، فعدد الأطباق من التمر 20 ÷ 4 = 5، ومن الحلوى 10 ÷ 2 = 5. العدد نفسه، فتملأ 5 أطباق.","ow":["4 أطباق تحتاج 16 تمرة و 8 قطع حلوى فقط، وتبقى مواد.","6 أطباق تحتاج 24 تمرة، ومعها 20 فقط.","10 أطباق تحتاج 40 تمرة، وهو أكثر مما معها.",""]},
  {"q":"ضُرب عدد في 3 ثم طُرح من الناتج 5 فصار 22. ما العدد؟","o":["7","8","9","10"],"a":2,"why":"نخمّن 9: 9 × 3 = 27 ثم 27 − 5 = 22 وهو المطلوب. بالعكس: 22 + 5 = 27 و 27 ÷ 3 = 9.","ow":["7 × 3 − 5 = 16 وليس 22.","8 × 3 − 5 = 19 وليس 22.","","10 × 3 − 5 = 25 وليس 22."]},
  {"q":"في حظيرة دجاج وأرانب: 10 رؤوس و 28 رجلًا. كم أرنبًا فيها؟","o":["3","4","5","6"],"a":1,"why":"نخمّن 4 أرانب و 6 دجاجات: الرؤوس 4 + 6 = 10 صحيحة، والأرجل 4 × 4 + 6 × 2 = 16 + 12 = 28 صحيحة أيضًا. إذن 4 أرانب.","ow":["3 أرانب و 7 دجاجات: الأرجل 12 + 14 = 26 وليست 28.","","5 أرانب و 5 دجاجات: الأرجل 20 + 10 = 30 وليست 28.","6 أرانب و 4 دجاجات: الأرجل 24 + 8 = 32 وليست 28."]},
  {"q":"عند غسل 5 سيارات صغيرة و 5 كبيرة كان الإجمالي 150 وهو أكبر من 140. ماذا نفعل؟","o":["نقلل عدد الكبيرة","نزيد عدد الكبيرة","نتوقف","نضرب في 2"],"a":0,"why":"الناتج 150 أكبر من المطلوب 140، فنخفضه بتقليل عدد السيارات الكبيرة (لأن سعرها أعلى) ونزيد الصغيرة، ثم نتحقق.","ow":["","زيادة الكبيرة ترفع الناتج وهو أكبر من المطلوب أصلًا.","لا نتوقف لأن الناتج لم يطابق المطلوب.","الضرب في 2 يضاعف الناتج ويبعدنا عن المطلوب."]},
  {"q":"ماذا نفعل بعد كتابة التخمين الأول في هذه الاستراتيجية؟","o":["نعتمده مباشرة","نحذفه","نضربه في 2","نتحقق منه بالتعويض"],"a":3,"why":"بعد التخمين الأول نتحقق منه بالتعويض في شروط المسألة. إذا لم يحقق الشروط نعدّله بحسب النتيجة ونكرر.","ow":["لا نعتمده قبل التحقق لأنه قد يكون خاطئًا.","لا نحذفه، فهو نقطة البداية التي نعدّل منها.","الضرب في 2 لا علاقة له بالتحقق.",""]},
  {"q":"مستطيل محيطه 20 سم وطوله 6 سم. كم عرضه؟","o":["14 سم","7 سم","4 سم","3 سم"],"a":2,"why":"محيط المستطيل = 2 × (الطول + العرض). 20 ÷ 2 = 10 فالطول + العرض = 10، والعرض = 10 − 6 = 4 سم. التحقق: 2 × (6 + 4) = 20.","ow":["14 سم تجعل الطول + العرض = 20 أي المحيط 40.","7 سم تجعل المحيط 2 × 13 = 26.","","3 سم تجعل المحيط 2 × 9 = 18."]},
  {"q":"التخمين يجب أن يكون صحيحًا من المرة الأولى.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فلا يشترط أن يكون التخمين الأول صحيحًا؛ نتحقق منه ثم نعدّله ونكرر حتى نصل إلى الإجابة الصحيحة.","ow":["«صح» تعني أن التخمين يجب أن يصيب من أول مرة، وهذا غير مطلوب.",""]},
  {"q":"نتحقق من التخمين بالتعويض في المسألة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فنعوض بالتخمين في المسألة ونرى هل يحقق الشروط. هذه خطوة التحقق. تذكّر: في التخمين والتحقق نخمّن، ونتحقق بالتعويض في شروط المسألة، ثم نعدّل التخمين حتى نصل للحل الصحيح.","ow":["","«خطأ» غير صحيحة، فالتحقق يكون بالتعويض."]},
  {"q":"إذا كان ناتج التخمين أكبر من المطلوب فنزيد القيم.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فإذا كان الناتج أكبر من المطلوب نقلل القيم، وإذا كان أقل نزيدها. تذكّر: في التخمين والتحقق نخمّن، ونتحقق بالتعويض في شروط المسألة، ثم نعدّل التخمين حتى نصل للحل الصحيح.","ow":["«صح» تعني زيادة القيم، وهذا يزيد الناتج الكبير أصلًا.",""]},
  {"q":"العدد 8 يحقق: العدد × 6 + 4 = 52","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالتعويض: 8 × 6 = 48 ثم 48 + 4 = 52 وهو المطلوب. تذكّر: في التخمين والتحقق نخمّن، ونتحقق بالتعويض في شروط المسألة، ثم نعدّل التخمين حتى نصل للحل الصحيح.","ow":["","«خطأ» غير صحيحة، فالتعويض يعطي 52 فعلًا."]},
  {"q":"التخمين والتحقق من استراتيجيات حل المسألة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالتخمين والتحقق استراتيجية لحل المسائل: نخمّن ثم نتحقق ثم نعدّل حتى نصل للحل.","ow":["","«خطأ» غير صحيحة، فهي من استراتيجيات حل المسألة في الكتاب."]}
];
window.BANK['m7']['m7-1-5'] = [
  {"q":"احسب قيمة ن + 7 إذا كانت ن = 5","o":["2","12","57","35"],"a":1,"why":"نعوّض عن ن بـ 5: ن + 7 = 5 + 7 = 12. تذكّر: المتغير رمز يمثل كمية غير معلومة، ونحسب العبارة الجبرية بتعويض قيمة المتغير ثم تنفيذ العمليات بالترتيب.","ow":["2 ناتج 7 − 5 وليس 5 + 7.","","57 يظهر عند كتابة الرقمين بجوار بعض وليس الجمع.","35 ناتج 5 × 7 وليس 5 + 7."]},
  {"q":"احسب قيمة 3س إذا كانت س = 4","o":["12","7","34","1"],"a":0,"why":"3س تعني 3 × س، فنعوّض س = 4: 3 × 4 = 12. تذكّر: المتغير رمز يمثل كمية غير معلومة، ونحسب العبارة الجبرية بتعويض قيمة المتغير ثم تنفيذ العمليات بالترتيب.","ow":["","7 ناتج 3 + 4، لكن 3س ضرب لا جمع.","34 كتابة الرقمين بجوار بعض وليس الناتج.","1 ناتج 4 − 3 وليس 3 × 4."]},
  {"q":"احسب قيمة 10 − ب إذا كانت ب = 3","o":["13","30","103","7"],"a":3,"why":"نعوّض عن ب بـ 3: 10 − ب = 10 − 3 = 7. تذكّر: المتغير رمز يمثل كمية غير معلومة، ونحسب العبارة الجبرية بتعويض قيمة المتغير ثم تنفيذ العمليات بالترتيب.","ow":["13 ناتج 10 + 3 وليس الطرح.","30 ناتج 10 × 3.","103 كتابة الرقمين بجوار بعض.",""]},
  {"q":"احسب قيمة 2أ + 1 إذا كانت أ = 6","o":["9","12","13","21"],"a":2,"why":"2أ + 1 مع أ = 6: الضرب أولًا 2 × 6 = 12 ثم نجمع 12 + 1 = 13. تذكّر: المتغير رمز يمثل كمية غير معلومة، ونحسب العبارة الجبرية بتعويض قيمة المتغير ثم تنفيذ العمليات بالترتيب.","ow":["9 ناتج 2 + 6 + 1 وليس 2 × 6 + 1.","12 هو 2 × 6 فقط، ونسينا جمع 1.","","21 لا يساوي 2 × 6 + 1، فالناتج الصحيح 13."]},
  {"q":"ما المعامل في العبارة 7ص ؟","o":["ص","7","14","1"],"a":1,"why":"المعامل هو العدد المضروب في المتغير. في 7ص العدد 7 هو المعامل، وص هو المتغير. تذكّر: المتغير رمز يمثل كمية غير معلومة، ونحسب العبارة الجبرية بتعويض قيمة المتغير ثم تنفيذ العمليات بالترتيب.","ow":["ص هو المتغير وليس المعامل.","","14 غير موجود في العبارة.","1 ليس هو العدد المضروب في ص هنا."]},
  {"q":"ما المتغير في العبارة 5ك + 2 ؟","o":["ك","5","2","7"],"a":0,"why":"المتغير هو الرمز (الحرف) الذي يمثل كمية غير معلومة. في 5ك + 2 المتغير هو ك. تذكّر: المتغير رمز يمثل كمية غير معلومة، ونحسب العبارة الجبرية بتعويض قيمة المتغير ثم تنفيذ العمليات بالترتيب.","ow":["","5 هو المعامل، فلا يصلح جوابًا هنا.","2 هو الحد الثابت (عدد معلوم).","7 غير موجود في العبارة، وهو ناتج 5 + 2."]},
  {"q":"كيف تُكتب العبارة 6 × ع بدون إشارة الضرب؟","o":["6 + ع","ع6","66ع","6ع"],"a":3,"why":"في الجبر نحذف إشارة الضرب بين العدد والمتغير، ونكتب المعامل أولًا ثم المتغير: 6 × ع = 6ع.","ow":["6 + ع جمع وليس ضربًا.","ع6 غير مألوفة، فالمعامل يُكتب قبل المتغير.","66ع تعني 66 × ع وليس 6 × ع.",""]},
  {"q":"احسب قيمة ع ÷ 2 + 1 إذا كانت ع = 8","o":["9","4","5","3"],"a":2,"why":"ع ÷ 2 + 1 مع ع = 8: القسمة أولًا 8 ÷ 2 = 4 ثم 4 + 1 = 5. تذكّر: المتغير رمز يمثل كمية غير معلومة، ونحسب العبارة الجبرية بتعويض قيمة المتغير ثم تنفيذ العمليات بالترتيب.","ow":["9 ناتج 8 + 1 فقط، وأهملنا القسمة.","4 هو ناتج القسمة فقط، ونسينا جمع 1.","","3 غير صحيح، فهو لا ينتج من الخطوات."]},
  {"q":"مساحة المستطيل م = ل × ع. ما مساحة مستطيل طوله 7 وعرضه 3؟","o":["10","21","14","73"],"a":1,"why":"مساحة المستطيل = الطول × العرض: م = 7 × 3 = 21. تذكّر: المتغير رمز يمثل كمية غير معلومة، ونحسب العبارة الجبرية بتعويض قيمة المتغير ثم تنفيذ العمليات بالترتيب.","ow":["10 ناتج الجمع 7 + 3.","","14 هو 7 × 2 وليس 7 × 3.","73 كتابة الرقمين بجوار بعض."]},
  {"q":"محيط المربع = 4 × ل. ما محيط مربع طول ضلعه 5؟","o":["20","9","25","45"],"a":0,"why":"محيط المربع = 4 × طول الضلع = 4 × 5 = 20. تذكّر: المتغير رمز يمثل كمية غير معلومة، ونحسب العبارة الجبرية بتعويض قيمة المتغير ثم تنفيذ العمليات بالترتيب.","ow":["","9 ناتج 4 + 5 وليس الضرب.","25 هو مساحة المربع 5 × 5 وليس محيطه.","45 كتابة الرقمين بجوار بعض."]},
  {"q":"عدد المربعات في الشكل ن هو ن + 2. كم مربعًا في الشكل 7؟","o":["5","14","72","9"],"a":3,"why":"عدد المربعات = ن + 2. للشكل 7 نعوّض ن = 7: 7 + 2 = 9. تذكّر: المتغير رمز يمثل كمية غير معلومة، ونحسب العبارة الجبرية بتعويض قيمة المتغير ثم تنفيذ العمليات بالترتيب.","ow":["5 ناتج 7 − 2، فلا يصلح جوابًا هنا.","14 ناتج 7 × 2، فلا يصلح جوابًا هنا.","72 كتابة الرقمين بجوار بعض.",""]},
  {"q":"احسب قيمة 3س − 2ص إذا كانت س = 4 ، ص = 1","o":["14","5","10","1"],"a":2,"why":"3س − 2ص مع س = 4 و ص = 1: 3 × 4 = 12 و 2 × 1 = 2، ثم 12 − 2 = 10. تذكّر: المتغير رمز يمثل كمية غير معلومة، ونحسب العبارة الجبرية بتعويض قيمة المتغير ثم تنفيذ العمليات بالترتيب.","ow":["14 ناتج الجمع 12 + 2 بدل الطرح.","5 هو 4 + 1 وليس نتيجة العبارة.","","1 هو 4 − 3 وليس العبارة."]},
  {"q":"احسب قيمة (س + 3) × 2 إذا كانت س = 2","o":["7","10","8","12"],"a":1,"why":"(س + 3) × 2 مع س = 2: القوس أولًا 2 + 3 = 5 ثم 5 × 2 = 10. تذكّر: المتغير رمز يمثل كمية غير معلومة، ونحسب العبارة الجبرية بتعويض قيمة المتغير ثم تنفيذ العمليات بالترتيب.","ow":["7 هو 2 + 3 + 2 جمع بدل الضرب.","","8 ناتج 2 × 4، لكن القوس 2 + 3 يساوي 5 وليس 4.","12 ناتج 6 × 2، لكن القوس 2 + 3 يساوي 5 وليس 6."]},
  {"q":"أي مما يأتي عبارة جبرية؟","o":["ن + 5","5 + 3 = 8","7 > 2","4 = 4"],"a":0,"why":"العبارة الجبرية تحتوي على متغير (حرف) وعمليات، مثل ن + 5. أما 5 + 3 = 8 فمعادلة عددية، و 7 > 2 متباينة عددية، و 4 = 4 تساوٍ عددي بلا متغير.","ow":["","5 + 3 = 8 جملة عددية فيها مساواة وليس فيها متغير.","7 > 2 مقارنة بين عددين وليس فيها متغير.","4 = 4 تساوٍ بين عددين وليس عبارة جبرية."]},
  {"q":"عدد أقطار مضلع = ن(ن − 3) ÷ 2. كم قطرًا للمضلع السداسي؟","o":["18","6","3","9"],"a":3,"why":"نعوّض ن = 6: 6 × (6 − 3) ÷ 2 = 6 × 3 ÷ 2 = 18 ÷ 2 = 9. للمضلع السداسي 9 أقطار. تذكّر: المتغير رمز يمثل كمية غير معلومة، ونحسب العبارة الجبرية بتعويض قيمة المتغير ثم تنفيذ العمليات بالترتيب.","ow":["18 هو 6 × 3 قبل القسمة على 2.","6 هو عدد الأضلاع وليس الأقطار.","3 هو ن − 3 فقط، ولم نكمل الحساب.",""]},
  {"q":"المتغير رمز يمثل كمية غير معلومة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالمتغير رمز (حرف) يمثل كمية غير معلومة أو قيمة قد تتغير. تذكّر: المتغير رمز يمثل كمية غير معلومة، ونحسب العبارة الجبرية بتعويض قيمة المتغير ثم تنفيذ العمليات بالترتيب.","ow":["","«خطأ» غير صحيحة، فهذا تعريف المتغير."]},
  {"q":"العبارة 5س تعني 5 + س.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فـ 5س تعني 5 × س (ضرب) وليس 5 + س (جمع). نحذف إشارة الضرب في الجبر.","ow":["«صح» تعني أن 5س جمع، لكنها ضرب.",""]},
  {"q":"المعامل في العبارة 8د هو 8.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالمعامل هو العدد المضروب في المتغير، وفي 8د هو 8. تذكّر: المتغير رمز يمثل كمية غير معلومة، ونحسب العبارة الجبرية بتعويض قيمة المتغير ثم تنفيذ العمليات بالترتيب.","ow":["","«خطأ» غير صحيحة، فالمعامل 8 فعلًا."]},
  {"q":"قيمة س + 2 عندما س = 3 تساوي 6.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فـ س + 2 عند س = 3 هي 3 + 2 = 5 وليست 6. تذكّر: المتغير رمز يمثل كمية غير معلومة، ونحسب العبارة الجبرية بتعويض قيمة المتغير ثم تنفيذ العمليات بالترتيب.","ow":["«صح» تعني أن الناتج 6، لكن 3 + 2 = 5.",""]},
  {"q":"الجبر فرع من الرياضيات يستعمل المتغيرات.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالجبر فرع من الرياضيات يستعمل الرموز (المتغيرات) لتمثيل كميات غير معلومة.","ow":["","«خطأ» غير صحيحة، فالمتغيرات أساس الجبر."]}
];
window.BANK['m7']['m7-1-6'] = [
  {"q":"ما حل المعادلة: ن + 6 = 10 ؟","o":["ن = 16","ن = 6","ن = 4","ن = 60"],"a":2,"why":"نبحث عن عدد إذا أضفنا إليه 6 صار 10. نطرح: 10 − 6 = 4. التحقق: 4 + 6 = 10. تذكّر: حل المعادلة هو القيمة التي تجعلها صحيحة، ونتحقق منه بتعويضه في المعادلة.","ow":["16 ناتج 10 + 6 وليس 10 − 6، والتحقق 16 + 6 = 22.","6 جزء من المعادلة، والتحقق 6 + 6 = 12 وليس 10.","","60 ناتج 10 × 6، وليس حل جمع."]},
  {"q":"ما حل المعادلة: ص − 3 = 9 ؟","o":["ص = 6","ص = 12","ص = 27","ص = 3"],"a":1,"why":"نبحث عن عدد إذا طرحنا منه 3 صار 9. نعكس الطرح بالجمع: 9 + 3 = 12. التحقق: 12 − 3 = 9.","ow":["6 ناتج 9 − 3، والتحقق 6 − 3 = 3 وليس 9.","","27 ناتج 9 × 3 وليس جمعًا.","3 هو العدد المطروح وليس الحل."]},
  {"q":"ما حل المعادلة: 5ك = 35 ؟","o":["ك = 7","ك = 30","ك = 40","ك = 175"],"a":0,"why":"5ك تعني 5 × ك. نقسم الناتج على 5: ك = 35 ÷ 5 = 7. التحقق: 5 × 7 = 35. تذكّر: حل المعادلة هو القيمة التي تجعلها صحيحة، ونتحقق منه بتعويضه في المعادلة.","ow":["","30 ناتج 35 − 5، لكن المعادلة ضرب فنقسم.","40 ناتج 35 + 5، والتحقق 5 × 40 = 200.","175 ناتج 35 × 5 أي ضربنا بدل القسمة."]},
  {"q":"ما حل المعادلة: ع ÷ 4 = 3 ؟","o":["ع = 7","ع = 1","ع = 34","ع = 12"],"a":3,"why":"ع ÷ 4 = 3، فنعكس القسمة بالضرب: ع = 3 × 4 = 12. التحقق: 12 ÷ 4 = 3. تذكّر: حل المعادلة هو القيمة التي تجعلها صحيحة، ونتحقق منه بتعويضه في المعادلة.","ow":["7 ناتج 3 + 4 وليس 3 × 4.","1 ناتج 4 − 3، فلا يصلح جوابًا هنا.","34 كتابة الرقمين بجوار بعض.",""]},
  {"q":"ما حل المعادلة: س + 12 = 20 ؟","o":["س = 32","س = 12","س = 8","س = 10"],"a":2,"why":"س + 12 = 20 فنطرح 12 من 20: س = 20 − 12 = 8. التحقق: 8 + 12 = 20. تذكّر: حل المعادلة هو القيمة التي تجعلها صحيحة، ونتحقق منه بتعويضه في المعادلة.","ow":["32 ناتج 20 + 12، وهو جمع بدل الطرح.","12 هو العدد المعطى وليس الحل.","","10 غير صحيح، فالتحقق 10 + 12 = 22 وليس 20."]},
  {"q":"ما حل المعادلة: 14 − ن = 9 ؟","o":["ن = 23","ن = 5","ن = 9","ن = 14"],"a":1,"why":"14 − ن = 9، فالمطلوب عدد نطرحه من 14 ليبقى 9: ن = 14 − 9 = 5. التحقق: 14 − 5 = 9.","ow":["23 ناتج 14 + 9، والتحقق 14 − 23 غير ممكن هنا.","","9 هو الباقي وليس العدد المطروح.","14 هو العدد الذي نطرح منه وليس الحل."]},
  {"q":"ما حل المعادلة: 8ب = 64 ؟","o":["ب = 8","ب = 56","ب = 72","ب = 6"],"a":0,"why":"8ب تعني 8 × ب. نقسم 64 على 8: ب = 64 ÷ 8 = 8. التحقق: 8 × 8 = 64. تذكّر: حل المعادلة هو القيمة التي تجعلها صحيحة، ونتحقق منه بتعويضه في المعادلة.","ow":["","56 ناتج 64 − 8، لكن المعادلة ضرب فنقسم.","72 ناتج 64 + 8، والتحقق 8 × 72 = 576.","6 غير صحيح، فـ 8 × 6 = 48 وليس 64."]},
  {"q":"أي مما يأتي معادلة؟","o":["3 + 4","7 × 2","5س","3 + 4 = 7"],"a":3,"why":"المعادلة جملة رياضية فيها إشارة التساوي (=). 3 + 4 = 7 فيها إشارة = وهي معادلة. تذكّر: حل المعادلة هو القيمة التي تجعلها صحيحة، ونتحقق منه بتعويضه في المعادلة.","ow":["3 + 4 عبارة بلا إشارة تساوٍ.","7 × 2 عبارة بلا إشارة تساوٍ.","5س عبارة جبرية بلا إشارة تساوٍ.",""]},
  {"q":"أي قيمة لـ س تحقق المعادلة 2 + س = 9 ؟","o":["5","6","7","8"],"a":2,"why":"نعوّض في المعادلة: 2 + 7 = 9 فالقيمة 7 تحقق المعادلة. تذكّر: حل المعادلة هو القيمة التي تجعلها صحيحة، ونتحقق منه بتعويضه في المعادلة.","ow":["2 + 5 = 7 وليس 9.","2 + 6 = 8 وليس 9.","","2 + 8 = 10 وليس 9."]},
  {"q":"ثمن الكتاب 8 ريالات. اشترى خالد ع كتب بمبلغ 40 ريالًا (8ع = 40). كم كتابًا اشترى؟","o":["4","5","6","32"],"a":1,"why":"المعادلة 8ع = 40، نقسم 40 على 8: ع = 5 كتب. التحقق: 8 × 5 = 40. تذكّر: حل المعادلة هو القيمة التي تجعلها صحيحة، ونتحقق منه بتعويضه في المعادلة.","ow":["4 كتب تكلف 32 ريالًا فقط.","","6 كتب تكلف 48 ريالًا.","32 هو ثمن 4 كتب وليس عدد الكتب."]},
  {"q":"مع سلمى س ريالًا، أعطتها أمها 5 ريالات فصار معها 20 (س + 5 = 20). كم كان معها؟","o":["15","25","5","10"],"a":0,"why":"المعادلة س + 5 = 20، فنطرح 5: س = 20 − 5 = 15. التحقق: 15 + 5 = 20. تذكّر: حل المعادلة هو القيمة التي تجعلها صحيحة، ونتحقق منه بتعويضه في المعادلة.","ow":["","25 ناتج 20 + 5 أي جمعنا بدل الطرح.","5 هو ما أعطته الأم وليس ما كان معها.","10 غير صحيح، فـ 10 + 5 = 15 وليس 20."]},
  {"q":"عمر أحمد ص، وأخوه أكبر منه بـ 3 سنوات وعمر الأخ 15 (ص + 3 = 15). كم عمر أحمد؟","o":["18","15","3","12"],"a":3,"why":"ص + 3 = 15، فنطرح 3 من 15: ص = 12 سنة. التحقق: 12 + 3 = 15. تذكّر: حل المعادلة هو القيمة التي تجعلها صحيحة، ونتحقق منه بتعويضه في المعادلة.","ow":["18 ناتج 15 + 3 وهو عمر لا يناسب المعادلة.","15 هو عمر الأخ وليس عمر أحمد.","3 هو فرق العمر وليس عمر أحمد.",""]},
  {"q":"يقطع سامي 6 كيلومترات يوميًا (6ي = 42). كم يومًا يقطع ليصل إلى 42 كم؟","o":["6","8","7","36"],"a":2,"why":"المعادلة 6ي = 42، نقسم: ي = 42 ÷ 6 = 7 أيام. التحقق: 6 × 7 = 42. تذكّر: حل المعادلة هو القيمة التي تجعلها صحيحة، ونتحقق منه بتعويضه في المعادلة.","ow":["6 أيام تعطي 36 كم فقط.","8 أيام تعطي 48 كم وهو أكثر من 42.","","36 ناتج 42 − 6 وليس عدد الأيام."]},
  {"q":"ماذا نسمي القيمة التي تجعل المعادلة صحيحة؟","o":["المتغير","الحل","المعامل","القوة"],"a":1,"why":"القيمة التي تجعل المعادلة صحيحة تسمى «حل المعادلة». مثلًا 4 هو حل ن + 6 = 10. تذكّر: حل المعادلة هو القيمة التي تجعلها صحيحة، ونتحقق منه بتعويضه في المعادلة.","ow":["المتغير هو الرمز نفسه (ن مثلًا)، وليس قيمته.","","المعامل هو العدد المضروب في المتغير.","القوة هي الأساس والأس وليس الحل."]},
  {"q":"ما حل المعادلة: ن − 8 = 2 ؟","o":["ن = 10","ن = 6","ن = 16","ن = 2"],"a":0,"why":"ن − 8 = 2، فنعكس الطرح بالجمع: ن = 2 + 8 = 10. التحقق: 10 − 8 = 2. تذكّر: حل المعادلة هو القيمة التي تجعلها صحيحة، ونتحقق منه بتعويضه في المعادلة.","ow":["","6 ناتج 8 − 2، والتحقق 6 − 8 غير صحيح.","16 ناتج 8 + 8، لا علاقة له بالمعادلة.","2 هو الناتج وليس قيمة ن."]},
  {"q":"حل المعادلة 3 + س = 7 هو س = 4.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فنعوّض س = 4: 3 + 4 = 7 وهو الطرف الثاني. تذكّر: حل المعادلة هو القيمة التي تجعلها صحيحة، ونتحقق منه بتعويضه في المعادلة.","ow":["","«خطأ» غير صحيحة، فالتعويض يحقق المعادلة."]},
  {"q":"حل المعادلة س − 2 = 5 هو س = 3.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فحل س − 2 = 5 هو س = 5 + 2 = 7. لو كانت س = 3 فإن 3 − 2 = 1 وليس 5.","ow":["«صح» تعني أن س = 3، لكن 3 − 2 = 1.",""]},
  {"q":"حل المعادلة 6س = 24 هو س = 4.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فـ 6س = 24 يعني 6 × س = 24، ونقسم: 24 ÷ 6 = 4. تذكّر: حل المعادلة هو القيمة التي تجعلها صحيحة، ونتحقق منه بتعويضه في المعادلة.","ow":["","«خطأ» غير صحيحة، فـ 6 × 4 = 24."]},
  {"q":"المعادلة جملة فيها إشارة التساوي.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالمعادلة جملة تحتوي على إشارة التساوي (=) بين عبارتين. تذكّر: حل المعادلة هو القيمة التي تجعلها صحيحة، ونتحقق منه بتعويضه في المعادلة.","ow":["","«خطأ» غير صحيحة، فهذا تعريف المعادلة."]},
  {"q":"إذا كان ص ÷ 2 = 5 فإن ص = 2.5","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فـ ص ÷ 2 = 5 تعني أن ص = 5 × 2 = 10، والقيمة 2.5 تحصل لو قسمنا خطأً 5 ÷ 2.","ow":["«صح» تعني أن ص = 2.5، لكن 2.5 ÷ 2 لا يساوي 5.",""]}
];
window.BANK['m7']['m7-1-7'] = [
  {"q":"أي خاصية تمثلها: 3 + 5 = 5 + 3 ؟","o":["التجميع","التوزيع","المحايد","الإبدال"],"a":3,"why":"في 3 + 5 = 5 + 3 بدّلنا ترتيب العددين فلم يتغير المجموع (8 في الحالتين). هذه خاصية الإبدال في الجمع.","ow":["التجميع يغيّر مواضع الأقواس لا ترتيب العددين.","التوزيع يربط الضرب بالجمع، ولا يظهر هنا.","المحايد يتعلق بالصفر أو الواحد، ولا يوجد هنا.",""]},
  {"q":"أي خاصية تمثلها: (2 + 3) + 4 = 2 + (3 + 4) ؟","o":["الإبدال","التوزيع","التجميع","المحايد"],"a":2,"why":"في (2 + 3) + 4 = 2 + (3 + 4) الأعداد بنفس الترتيب لكن تغيّر موضع الأقواس، أي ما نحسبه أولًا. هذه خاصية التجميع (5 + 4 = 9 و 2 + 7 = 9).","ow":["الإبدال يغيّر ترتيب الأعداد، وهنا لم يتغير ترتيبها.","التوزيع يحتاج ضربًا فوق قوس جمع.","","المحايد يحتاج صفرًا أو واحدًا."]},
  {"q":"أي خاصية تمثلها: 7 × (2 + 5) = 7 × 2 + 7 × 5 ؟","o":["الإبدال","التوزيع","التجميع","المحايد"],"a":1,"why":"في 7 × (2 + 5) = 7 × 2 + 7 × 5 ضربنا العدد 7 في كل حد داخل القوس. هذه خاصية التوزيع (الطرفان يساويان 49).","ow":["الإبدال يغيّر ترتيب العددين فقط.","","التجميع يغيّر مواضع الأقواس في عملية واحدة.","المحايد يحتاج صفرًا أو واحدًا."]},
  {"q":"أي خاصية تمثلها: 9 + 0 = 9 ؟","o":["العنصر المحايد","الإبدال","التجميع","التوزيع"],"a":0,"why":"9 + 0 = 9: جمع الصفر لا يغيّر العدد. لذلك الصفر هو العنصر المحايد للجمع. تذكّر: خصائص الجمع والضرب: الإبدال (تغيير الترتيب)، التجميع (تغيير الأقواس)، التوزيع، والعنصر المحايد (0 للجمع و 1 للضرب).","ow":["","الإبدال يغيّر الترتيب، وهنا لا يوجد تبديل.","التجميع يحتاج ثلاثة أعداد وأقواسًا.","التوزيع يحتاج ضربًا فوق قوس."]},
  {"q":"احسب باستعمال خاصية التوزيع: 6(4 + 3)","o":["27","24","18","42"],"a":3,"why":"نوزّع 6 على كل حد: 6 × 4 = 24 و 6 × 3 = 18، والمجموع 24 + 18 = 42. وللتحقق: 6 × 7 = 42.","ow":["27 هو 24 + 3 أي ضربنا 6 في 4 فقط وجمعنا 3.","24 هو 6 × 4 فقط، ونسينا 6 × 3.","18 هو 6 × 3 فقط، ونسينا 6 × 4.",""]},
  {"q":"احسب: 8(5) + 8(2)","o":["80","40","56","16"],"a":2,"why":"نجمع بالتوزيع العكسي: 8(5) + 8(2) = 8(5 + 2) = 8 × 7 = 56. أو 40 + 16 = 56. تذكّر: خصائص الجمع والضرب: الإبدال (تغيير الترتيب)، التجميع (تغيير الأقواس)، التوزيع، والعنصر المحايد (0 للجمع و 1 للضرب).","ow":["80 هو 8 × 10 وليس مطابقًا.","40 هو 8 × 5 فقط، ونسينا 8 × 2.","","16 هو 8 × 2 فقط، ونسينا 8 × 5."]},
  {"q":"احسب ذهنيًا: 25 × 4 × 7","o":["280","700","175","1000"],"a":1,"why":"نبدل ونجمع: 25 × 4 = 100 ثم 100 × 7 = 700. خاصيتا الإبدال والتجميع تسهّلان الحساب.","ow":["280 هو 4 × 7 × 10 وليس 25 × 4 × 7.","","175 هو 25 × 7 فقط، ونسينا الضرب في 4.","1000 غير صحيح؛ 100 × 7 = 700 وليس 1000."]},
  {"q":"احسب باستعمال التوزيع: 5 × 63 = 5(60 + 3)","o":["315","300","65","183"],"a":0,"why":"نجزئ 63 إلى 60 + 3: 5 × 60 = 300 و 5 × 3 = 15، فالمجموع 315. تذكّر: خصائص الجمع والضرب: الإبدال (تغيير الترتيب)، التجميع (تغيير الأقواس)، التوزيع، والعنصر المحايد (0 للجمع و 1 للضرب).","ow":["","300 هو 5 × 60 فقط، ونسينا 5 × 3.","65 هو 5 + 60، أي جمعنا بدل الضرب.","183 غير صحيح؛ الناتج 315."]},
  {"q":"ما العنصر المحايد في عملية الجمع؟","o":["1","10","−1","0"],"a":3,"why":"العنصر المحايد للجمع هو 0، لأن أي عدد زائد 0 يساوي العدد نفسه (مثلًا 8 + 0 = 8).","ow":["1 محايد للضرب وليس للجمع.","10 يغيّر العدد عند الجمع (8 + 10 = 18).","−1 يغيّر العدد عند الجمع (8 + (−1) = 7).",""]},
  {"q":"ما العنصر المحايد في عملية الضرب؟","o":["0","10","1","2"],"a":2,"why":"العنصر المحايد للضرب هو 1، لأن أي عدد × 1 يساوي العدد نفسه (مثلًا 8 × 1 = 8). تذكّر: خصائص الجمع والضرب: الإبدال (تغيير الترتيب)، التجميع (تغيير الأقواس)، التوزيع، والعنصر المحايد (0 للجمع و 1 للضرب).","ow":["0 يجعل الناتج صفرًا (8 × 0 = 0).","10 يغيّر العدد عند الضرب (8 × 10 = 80).","","2 يضاعف العدد (8 × 2 = 16)."]},
  {"q":"أي خاصية تمثلها: 5 × (3 × 2) = (5 × 3) × 2 ؟","o":["الإبدال","التجميع","التوزيع","المحايد"],"a":1,"why":"في 5 × (3 × 2) = (5 × 3) × 2 الأعداد بنفس الترتيب وتغير موضع الأقواس. هذه خاصية التجميع في الضرب (30 في الحالتين).","ow":["الإبدال يغيّر ترتيب الأعداد، ولم يتغير هنا.","","التوزيع يحتاج ضربًا فوق جمع.","المحايد يحتاج 1 أو 0."]},
  {"q":"أي خاصية تمثلها: 8 × 6 = 6 × 8 ؟","o":["الإبدال في الضرب","التجميع","التوزيع","المحايد"],"a":0,"why":"في 8 × 6 = 6 × 8 بدّلنا ترتيب العاملين فلم يتغير الناتج (48). هذه خاصية الإبدال في الضرب.","ow":["","التجميع يغيّر الأقواس لا الترتيب.","التوزيع يحتاج ضربًا فوق جمع.","المحايد يحتاج 1 أو 0."]},
  {"q":"أعد الكتابة ثم احسب: 3(7) + 3(3)","o":["21","27","9","30"],"a":3,"why":"نجمع بالتوزيع العكسي: 3(7) + 3(3) = 3(7 + 3) = 3 × 10 = 30. أو 21 + 9 = 30. تذكّر: خصائص الجمع والضرب: الإبدال (تغيير الترتيب)، التجميع (تغيير الأقواس)، التوزيع، والعنصر المحايد (0 للجمع و 1 للضرب).","ow":["21 هو 3 × 7 فقط، ونسينا 3 × 3.","27 هو 21 + 6، وليس 3 × 3 = 9.","9 هو 3 × 3 فقط، ونسينا 3 × 7.",""]},
  {"q":"احسب ذهنيًا: 4 × 15 × 5","o":["75","100","300","200"],"a":2,"why":"نغيّر الترتيب لنسهّل: 4 × 5 = 20 ثم 15 × 20 = 300 (15 × 20 = 15 × 2 × 10 = 300).","ow":["75 هو 15 × 5 فقط، ونسينا الضرب في 4.","100 هو 4 × 25 وليس 4 × 15 × 5.","","200 غير صحيح؛ 15 × 20 = 300."]},
  {"q":"احسب بالتوزيع: 9 × 102 = 9(100 + 2)","o":["900","918","111","902"],"a":1,"why":"نجزئ 102 إلى 100 + 2: 9 × 100 = 900 و 9 × 2 = 18، والمجموع 918. تذكّر: خصائص الجمع والضرب: الإبدال (تغيير الترتيب)، التجميع (تغيير الأقواس)، التوزيع، والعنصر المحايد (0 للجمع و 1 للضرب).","ow":["900 هو 9 × 100 فقط، ونسينا 9 × 2.","","111 هو 9 + 102 أي جمعنا بدل الضرب.","902 هو 900 + 2 أي ضربنا 9 في 100 فقط وجمعنا 2."]},
  {"q":"عملية الطرح لها خاصية الإبدال.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالطرح ليس له خاصية الإبدال: 5 − 3 = 2 بينما 3 − 5 = −2. ترتيب العددين يغيّر الناتج.","ow":["«صح» تعني أن 5 − 3 = 3 − 5، وهذا غير صحيح.",""]},
  {"q":"6 + 0 = 6 مثال على العنصر المحايد.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فجمع الصفر لا يغيّر العدد (6 + 0 = 6)، فالصفر عنصر محايد للجمع. تذكّر: خصائص الجمع والضرب: الإبدال (تغيير الترتيب)، التجميع (تغيير الأقواس)، التوزيع، والعنصر المحايد (0 للجمع و 1 للضرب).","ow":["","«خطأ» غير صحيحة، فهذا هو مثال المحايد الجمعي."]},
  {"q":"4 × 1 = 1","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فـ 4 × 1 = 4 لأن 1 هو العنصر المحايد للضرب، ولا يعطي 1. تذكّر: خصائص الجمع والضرب: الإبدال (تغيير الترتيب)، التجميع (تغيير الأقواس)، التوزيع، والعنصر المحايد (0 للجمع و 1 للضرب).","ow":["«صح» تعني أن الناتج 1، لكن الضرب في 1 يترك العدد 4 كما هو.",""]},
  {"q":"5 + 3 + 2 = 5 + (3 + 2) مثال على خاصية التجميع.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالأعداد بنفس الترتيب وتغير موضع الأقواس فقط: (5 + 3) + 2 = 5 + (3 + 2) = 10. هذه خاصية التجميع.","ow":["","«خطأ» غير صحيحة، فهذا مثال على التجميع."]},
  {"q":"عملية القسمة لها خاصية الإبدال.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالقسمة ليس لها خاصية الإبدال: 6 ÷ 3 = 2 بينما 3 ÷ 6 = 0.5. تذكّر: خصائص الجمع والضرب: الإبدال (تغيير الترتيب)، التجميع (تغيير الأقواس)، التوزيع، والعنصر المحايد (0 للجمع و 1 للضرب).","ow":["«صح» تعني أن الترتيب لا يهم، لكن 6 ÷ 3 لا تساوي 3 ÷ 6.",""]}
];
window.BANK['m7']['m7-1-8'] = [
  {"q":"ثمن الكتاب 7 ريالات. كم ثمن 6 كتب؟","o":["42 ريالًا","13 ريالًا","36 ريالًا","49 ريالًا"],"a":0,"why":"ثمن الكتاب الواحد 7، فقاعدة الدالة × 7. لـ 6 كتب: 6 × 7 = 42 ريالًا. تذكّر: الدالة تربط كل مدخل (المجال) بمخرج واحد فقط (المدى) بقاعدة، فنعوّض المدخل لنحصل على المخرج.","ow":["","13 ريالًا ناتج 6 + 7 وليس الضرب.","36 ريالًا ناتج 6 × 6 وليس 6 × 7.","49 ريالًا ناتج 7 × 7 وليس 6 × 7."]},
  {"q":"ماذا نسمي مجموعة قيم المدخلات في الدالة؟","o":["المدى","القاعدة","الجدول","المجال"],"a":3,"why":"مجموعة قيم المدخلات (قيم س) في الدالة تسمى المجال. تذكّر: الدالة تربط كل مدخل (المجال) بمخرج واحد فقط (المدى) بقاعدة، فنعوّض المدخل لنحصل على المخرج.","ow":["المدى هو مجموعة المخرجات.","القاعدة هي العملية التي تجري على المدخلات.","الجدول وسيلة لعرض المدخلات والمخرجات وليس اسم مجموعتها.",""]},
  {"q":"ماذا نسمي مجموعة قيم المخرجات في الدالة؟","o":["المجال","القاعدة","المدى","المعامل"],"a":2,"why":"مجموعة قيم المخرجات (قيم ص) في الدالة تسمى المدى. تذكّر: الدالة تربط كل مدخل (المجال) بمخرج واحد فقط (المدى) بقاعدة، فنعوّض المدخل لنحصل على المخرج.","ow":["المجال هو مجموعة المدخلات.","القاعدة هي العملية على المدخلات.","","المعامل هو العدد المضروب في المتغير."]},
  {"q":"إذا كانت ص = 5س فما قيمة ص عندما س = 3 ؟","o":["8","15","35","2"],"a":1,"why":"ص = 5س، نعوّض س = 3: ص = 5 × 3 = 15. تذكّر: الدالة تربط كل مدخل (المجال) بمخرج واحد فقط (المدى) بقاعدة، فنعوّض المدخل لنحصل على المخرج.","ow":["8 ناتج 5 + 3 وليس الضرب.","","35 كتابة الرقمين بجوار بعض.","2 ناتج 5 − 3، فلا يصلح جوابًا هنا."]},
  {"q":"إذا كانت ص = س + 4 فما قيمة ص عندما س = 6 ؟","o":["10","24","2","46"],"a":0,"why":"ص = س + 4، نعوّض س = 6: ص = 6 + 4 = 10. تذكّر: الدالة تربط كل مدخل (المجال) بمخرج واحد فقط (المدى) بقاعدة، فنعوّض المدخل لنحصل على المخرج.","ow":["","24 ناتج 6 × 4 وليس الجمع.","2 ناتج 6 − 4، فلا يصلح جوابًا هنا.","46 كتابة الرقمين بجوار بعض."]},
  {"q":"إذا كانت ص = 2س − 1 فما قيمة ص عندما س = 5 ؟","o":["11","4","7","9"],"a":3,"why":"ص = 2س − 1، نعوّض س = 5: 2 × 5 = 10 ثم 10 − 1 = 9. تذكّر: الدالة تربط كل مدخل (المجال) بمخرج واحد فقط (المدى) بقاعدة، فنعوّض المدخل لنحصل على المخرج.","ow":["11 ناتج 10 + 1 أي جمعنا بدل الطرح.","4 غير صحيح؛ 5 − 1 = 4 ولم نضرب في 2.","7 غير صحيح؛ الضرب 2 × 5 يعطي 10 لا 8.",""]},
  {"q":"جدول الدالة: (1 ← 4) ، (2 ← 8) ، (3 ← 12). ما معادلتها؟","o":["ص = س + 3","ص = س + 4","ص = 4 س","ص = 12 س"],"a":2,"why":"نقسم كل مخرج على المدخل: 4 ÷ 1 = 4 و 8 ÷ 2 = 4 و 12 ÷ 3 = 4، فالمخرج = 4 × المدخل: ص = 4س.","ow":["ص = س + 3 تعطي 4 و 5 و 6، وليست 4 و 8 و 12.","ص = س + 4 تعطي 5 و 6 و 7.","","ص = 12س تعطي 12 و 24 و 36."]},
  {"q":"جدول الدالة: (1 ← 5) ، (2 ← 6) ، (3 ← 7). ما معادلتها؟","o":["ص = 5 س","ص = س + 4","ص = س + 5","ص = 4 س"],"a":1,"why":"المخرج يزيد على المدخل دائمًا بمقدار 4: 1 + 4 = 5 و 2 + 4 = 6 و 3 + 4 = 7. فالمعادلة ص = س + 4.","ow":["ص = 5س تعطي 5 و 10 و 15.","","ص = س + 5 تعطي 6 و 7 و 8.","ص = 4س تعطي 4 و 8 و 12."]},
  {"q":"قاعدة دالة: × 6 ، والمجال {1 ، 2 ، 3}. ما المدى؟","o":["{6 ، 12 ، 18}","{7 ، 8 ، 9}","{1 ، 2 ، 3}","{6 ، 7 ، 8}"],"a":0,"why":"القاعدة × 6 نطبقها على كل مدخل: 1 × 6 = 6 و 2 × 6 = 12 و 3 × 6 = 18. المدى {6 ، 12 ، 18}.","ow":["","{7 ، 8 ، 9} ناتج الجمع 6 + مدخل وليس الضرب.","{1 ، 2 ، 3} هو المجال (المدخلات) وليس المدى.","{6 ، 7 ، 8} غير صحيح؛ القاعدة ضرب."]},
  {"q":"ماذا نسمي العلاقة التي يرتبط فيها كل مدخل بمخرج واحد فقط؟","o":["معادلة فقط","متغيرًا","قوة","دالة"],"a":3,"why":"الدالة علاقة يرتبط فيها كل مدخل بمخرج واحد فقط. تذكّر: الدالة تربط كل مدخل (المجال) بمخرج واحد فقط (المدى) بقاعدة، فنعوّض المدخل لنحصل على المخرج.","ow":["المعادلة جملة فيها تساوٍ وليست هي التعريف.","المتغير رمز يمثل كمية غير معلومة.","القوة هي أساس مرفوع إلى أس.",""]},
  {"q":"تسير سيارة 40 كم في الساعة (ص = 40 س). كم تقطع في 3 ساعات؟","o":["43 كم","80 كم","120 كم","13 كم"],"a":2,"why":"القاعدة ص = 40س، نعوّض س = 3: 40 × 3 = 120 كم. تذكّر: الدالة تربط كل مدخل (المجال) بمخرج واحد فقط (المدى) بقاعدة، فنعوّض المدخل لنحصل على المخرج.","ow":["43 كم ناتج 40 + 3 وليس الضرب.","80 كم تكفي لساعتين فقط (40 × 2).","","13 كم غير صحيح؛ 40 × 3 = 120."]},
  {"q":"في الدالة ص = 10 س، إذا كان المخرج 70 فما المدخل؟","o":["60","7","80","700"],"a":1,"why":"ص = 10س والمخرج 70، فنقسم: س = 70 ÷ 10 = 7. التحقق: 10 × 7 = 70. تذكّر: الدالة تربط كل مدخل (المجال) بمخرج واحد فقط (المدى) بقاعدة، فنعوّض المدخل لنحصل على المخرج.","ow":["60 ناتج 70 − 10 وليس القسمة.","","80 ناتج 70 + 10 وليس القسمة.","700 ناتج 70 × 10 أي ضربنا بدل القسمة."]},
  {"q":"ماذا تمثل قاعدة الدالة؟","o":["العملية التي تجري على المدخلات","مجموعة المخرجات","عدد المدخلات","ثمن المخرجات فقط"],"a":0,"why":"قاعدة الدالة تصف العملية التي تجري على المدخلات لنحصل على المخرجات، مثل «× 6» أو «+ 3».","ow":["","مجموعة المخرجات تسمى المدى.","عدد المدخلات ليس القاعدة.","القاعدة ليست ثمنًا؛ هي عملية عامة."]},
  {"q":"ثمن القلم 3 ريالات. كم ثمن 8 أقلام؟","o":["11 ريالًا","38 ريالًا","21 ريالًا","24 ريالًا"],"a":3,"why":"ثمن القلم الواحد 3، فثمن 8 أقلام 3 × 8 = 24 ريالًا. تذكّر: الدالة تربط كل مدخل (المجال) بمخرج واحد فقط (المدى) بقاعدة، فنعوّض المدخل لنحصل على المخرج.","ow":["11 ريالًا ناتج 3 + 8 وليس الضرب.","38 ريالًا كتابة الرقمين بجوار بعض.","21 ريالًا ثمن 7 أقلام (3 × 7).",""]},
  {"q":"جدول الدالة: (2 ← 1) ، (4 ← 2) ، (6 ← 3). ما معادلتها؟","o":["ص = 2 س","ص = س − 1","ص = س ÷ 2","ص = س + 2"],"a":2,"why":"المخرج نصف المدخل، أي نقسم المدخل على 2: 2 ÷ 2 = 1 و 4 ÷ 2 = 2 و 6 ÷ 2 = 3. فالمعادلة ص = س ÷ 2.","ow":["ص = 2س تعطي 4 و 8 و 12، والمطلوب 1 و 2 و 3.","ص = س − 1 تعطي 1 و 3 و 5.","","ص = س + 2 تعطي 4 و 6 و 8."]},
  {"q":"في ص = 3س إذا كانت س = 2 فإن ص = 6.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فنعوّض س = 2 في ص = 3س: 3 × 2 = 6. تذكّر: الدالة تربط كل مدخل (المجال) بمخرج واحد فقط (المدى) بقاعدة، فنعوّض المدخل لنحصل على المخرج.","ow":["","«خطأ» غير صحيحة، فالناتج فعلًا 6."]},
  {"q":"المجال هو مجموعة المخرجات.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالمجال هو مجموعة المدخلات (قيم س)، أما المخرجات فمجموعتها تسمى المدى.","ow":["«صح» تعني أن المجال مخرجات، لكنه مدخلات.",""]},
  {"q":"في الدالة يمكن أن يكون للمدخل الواحد أكثر من مخرج.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالدالة يرتبط فيها كل مدخل بمخرج واحد فقط، فلا يكون للمدخل الواحد مخرجان.","ow":["«صح» تعني أن المدخل يعطي أكثر من مخرج، وهذا ليس دالة.",""]},
  {"q":"المعادلة ص = س + 1 تمثل دالة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فلكل قيمة لـ س قيمة واحدة فقط لـ ص (س + 1)، فهي دالة. تذكّر: الدالة تربط كل مدخل (المجال) بمخرج واحد فقط (المدى) بقاعدة، فنعوّض المدخل لنحصل على المخرج.","ow":["","«خطأ» غير صحيحة، فالمعادلة تعطي لكل مدخل مخرجًا واحدًا."]},
  {"q":"المدى هو مجموعة المدخلات.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالمدى هو مجموعة المخرجات، أما المدخلات فمجموعتها المجال. تذكّر: الدالة تربط كل مدخل (المجال) بمخرج واحد فقط (المدى) بقاعدة، فنعوّض المدخل لنحصل على المخرج.","ow":["«صح» تعني أن المدى مدخلات، لكنه مخرجات.",""]}
];
window.BANK['m7']['m7-2-1'] = [
  {"q":"اكتب عددًا صحيحًا يمثل: 10 درجات تحت الصفر","o":["+10","−10","10 − 0","0"],"a":1,"why":"كلمة «تحت» الصفر تدل على عدد سالب، فنكتب −10. الأعداد السالبة تمثل ما هو أقل من الصفر مثل درجات الحرارة تحت الصفر.","ow":["+10 عدد موجب يدل على «فوق» الصفر.","","10 − 0 عبارة طرح وليست عددًا يمثل الحالة.","0 يعني لا درجات، لكن المقصود 10 درجات تحت الصفر."]},
  {"q":"اكتب عددًا صحيحًا يمثل: 15 مترًا فوق سطح البحر","o":["+15","−15","0","−1"],"a":0,"why":"كلمة «فوق» سطح البحر تدل على عدد موجب، فنكتب +15. الارتفاع فوق الصفر يمثل بعدد موجب.","ow":["","−15 يدل على 15 مترًا تحت سطح البحر.","0 هو مستوى سطح البحر نفسه وليس 15 مترًا فوقه.","−1 يدل على متر واحد تحت سطح البحر."]},
  {"q":"اكتب عددًا صحيحًا يمثل: ربح 20 ريالًا","o":["−20","0","+2","+20"],"a":3,"why":"الربح زيادة في المال، فيمثل بعدد موجب: +20. تذكّر: القيمة المطلقة هي بُعد العدد عن الصفر على خط الأعداد ولا تكون سالبة، والموجب يمين الصفر والسالب يساره.","ow":["−20 يمثل خسارة 20 ريالًا.","0 يعني لا ربح ولا خسارة.","+2 يمثل ربح ريالين فقط وليس 20.",""]},
  {"q":"اكتب عددًا صحيحًا يمثل: خسارة 8 ريالات","o":["+8","0","−8","+80"],"a":2,"why":"الخسارة نقص في المال، فتمثل بعدد سالب: −8. تذكّر: القيمة المطلقة هي بُعد العدد عن الصفر على خط الأعداد ولا تكون سالبة، والموجب يمين الصفر والسالب يساره.","ow":["+8 يمثل ربحًا وليس خسارة.","0 يعني لا ربح ولا خسارة.","","+80 يمثل ربح 80 ريالًا."]},
  {"q":"ما قيمة |−9| ؟","o":["−9","9","0","18"],"a":1,"why":"القيمة المطلقة هي المسافة بين العدد والصفر على خط الأعداد، والمسافة لا تكون سالبة. العدد −9 يبعد 9 وحدات عن الصفر فـ |−9| = 9.","ow":["−9 هو العدد نفسه، والمسافة لا تكون سالبة.","","0 هي قيمة الصفر فقط، و −9 يبعد 9 وحدات.","18 ليس مسافة −9 عن الصفر؛ هي 9."]},
  {"q":"ما قيمة |12| ؟","o":["12","−12","0","24"],"a":0,"why":"|12| هي المسافة بين 12 والصفر، وهي 12 وحدة. القيمة المطلقة للعدد الموجب تساوي العدد نفسه.","ow":["","−12 غير صحيح لأن المسافة لا تكون سالبة.","0 هي قيمة الصفر وليس 12.","24 غير صحيح؛ المسافة 12 فقط."]},
  {"q":"احسب: |−7| + |3|","o":["4","−4","−10","10"],"a":3,"why":"|−7| = 7 و |3| = 3 لأن القيمة المطلقة مسافة عن الصفر. إذن 7 + 3 = 10. تذكّر: القيمة المطلقة هي بُعد العدد عن الصفر على خط الأعداد ولا تكون سالبة، والموجب يمين الصفر والسالب يساره.","ow":["4 يظهر لو طرحنا 7 − 3 بدل الجمع.","−4 غير صحيح؛ القيمتان المطلقتان موجبتان ونجمعهما.","−10 غير صحيح؛ القيم المطلقة لا تكون سالبة.",""]},
  {"q":"احسب: |−10| − |4|","o":["14","−6","6","−14"],"a":2,"why":"|−10| = 10 و |4| = 4، ثم نطرح: 10 − 4 = 6. تذكّر: القيمة المطلقة هي بُعد العدد عن الصفر على خط الأعداد ولا تكون سالبة، والموجب يمين الصفر والسالب يساره.","ow":["14 يظهر لو جمعنا بدل الطرح.","−6 غير صحيح؛ 10 − 4 = 6 موجب.","","−14 غير صحيح؛ القيم المطلقة موجبة والعملية طرح."]},
  {"q":"أي عددين لهما القيمة المطلقة 6 ؟","o":["6 و 0","6 و −6","−6 و 0","12 و −12"],"a":1,"why":"6 و −6 كلاهما يبعد 6 وحدات عن الصفر، فقيمتهما المطلقة 6. تذكّر: القيمة المطلقة هي بُعد العدد عن الصفر على خط الأعداد ولا تكون سالبة، والموجب يمين الصفر والسالب يساره.","ow":["6 و 0: الصفر قيمته المطلقة 0 وليس 6.","","−6 و 0: الصفر قيمته المطلقة 0 وليس 6.","12 و −12 قيمتهما المطلقة 12 وليس 6."]},
  {"q":"أي مما يأتي عدد صحيح موجب؟","o":["+12","−12","0","−1"],"a":0,"why":"العدد الصحيح الموجب أكبر من الصفر، مثل +12 (أو 12). تذكّر: القيمة المطلقة هي بُعد العدد عن الصفر على خط الأعداد ولا تكون سالبة، والموجب يمين الصفر والسالب يساره.","ow":["","−12 عدد سالب (أقل من الصفر).","0 ليس موجبًا ولا سالبًا.","−1 عدد سالب (أقل من الصفر)."]},
  {"q":"كم وحدة يبعد العدد −8 عن الصفر؟","o":["−8 وحدة","0 وحدة","16 وحدة","8 وحدات"],"a":3,"why":"عدد الوحدات بين العدد والصفر هو قيمته المطلقة، و |−8| = 8، فالعدد −8 يبعد 8 وحدات.","ow":["المسافة لا تكون سالبة، فلا نقول −8 وحدة.","0 يعني أنه على الصفر نفسه.","16 ضعف المسافة الصحيحة؛ المسافة 8 فقط.",""]},
  {"q":"أين تقع الأعداد الموجبة على خط الأعداد؟","o":["يسار الصفر","عند الصفر","يمين الصفر","تحت الصفر"],"a":2,"why":"الأعداد الموجبة تقع يمين الصفر على خط الأعداد، والسالبة يساره. تذكّر: القيمة المطلقة هي بُعد العدد عن الصفر على خط الأعداد ولا تكون سالبة، والموجب يمين الصفر والسالب يساره.","ow":["يسار الصفر تقع الأعداد السالبة.","عند الصفر يقع الصفر نفسه فقط.","","«تحت الصفر» تعبير عن السالب وليس موضعًا على خط أفقي."]},
  {"q":"هبط غواص 5 م وارتفع آخر 4 م. أي القيمتين المطلقتين أكبر؟","o":["القيمة المطلقة للارتفاع (4)","القيمة المطلقة للهبوط (5)","متساويتان","لا يمكن المقارنة"],"a":1,"why":"القيمة المطلقة للهبوط |−5| = 5 وللارتفاع |4| = 4. و 5 أكبر من 4، فقيمة الهبوط المطلقة أكبر.","ow":["|4| = 4 أصغر من |−5| = 5.","","القيمتان ليستا متساويتين (5 و 4).","يمكن المقارنة بعد حساب القيمتين المطلقتين."]},
  {"q":"ما القيمة المطلقة للصفر؟","o":["0","1","−1","10"],"a":0,"why":"القيمة المطلقة للصفر 0 لأن الصفر لا يبعد عن نفسه. تذكّر: القيمة المطلقة هي بُعد العدد عن الصفر على خط الأعداد ولا تكون سالبة، والموجب يمين الصفر والسالب يساره.","ow":["","1 يبعد وحدة عن الصفر وليس الصفر نفسه.","−1 عدد آخر والقيمة المطلقة لا تكون سالبة.","10 يبعد 10 وحدات عن الصفر."]},
  {"q":"ما العدد الصحيح الذي يبعد 3 وحدات نحو اليمين عن الصفر؟","o":["−3","0","+6","+3"],"a":3,"why":"الاتجاه نحو اليمين من الصفر موجب، فالعدد الذي يبعد 3 وحدات يمينًا هو +3. تذكّر: القيمة المطلقة هي بُعد العدد عن الصفر على خط الأعداد ولا تكون سالبة، والموجب يمين الصفر والسالب يساره.","ow":["−3 يبعد 3 وحدات نحو اليسار.","0 هو الصفر نفسه.","+6 يبعد 6 وحدات وليس 3.",""]},
  {"q":"القيمة المطلقة لأي عدد لا تكون سالبة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالقيمة المطلقة هي مسافة العدد عن الصفر، والمسافة لا تكون سالبة (قد تساوي 0 أو أكثر).","ow":["","«خطأ» غير صحيحة، فلا توجد قيمة مطلقة سالبة."]},
  {"q":"|−5| = −5","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالعدد −5 يبعد 5 وحدات عن الصفر، فـ |−5| = 5 وليس −5. تذكّر: القيمة المطلقة هي بُعد العدد عن الصفر على خط الأعداد ولا تكون سالبة، والموجب يمين الصفر والسالب يساره.","ow":["«صح» تعني أن القيمة المطلقة سالبة، والمسافة لا تكون سالبة.",""]},
  {"q":"الصفر عدد موجب.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالصفر ليس موجبًا ولا سالبًا؛ الموجب أكبر من الصفر والسالب أصغر منه.","ow":["«صح» تعني أن الصفر موجب، لكنه فاصل بين الموجب والسالب.",""]},
  {"q":"العدد −3 يقع يسار الصفر على خط الأعداد.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالأعداد السالبة تقع يسار الصفر على خط الأعداد، ومنها −3. تذكّر: القيمة المطلقة هي بُعد العدد عن الصفر على خط الأعداد ولا تكون سالبة، والموجب يمين الصفر والسالب يساره.","ow":["","«خطأ» غير صحيحة، فاليسار للسالب."]},
  {"q":"ربح 50 ريالًا يُمثَّل بالعدد −50.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالربح يمثل بعدد موجب +50 وليس −50. العدد −50 يمثل خسارة. تذكّر: القيمة المطلقة هي بُعد العدد عن الصفر على خط الأعداد ولا تكون سالبة، والموجب يمين الصفر والسالب يساره.","ow":["«صح» تعني أن الربح سالب، لكنه موجب.",""]}
];
