window.BANK['m7']['m7-3-1'] = [
  {"q":"كلمة «المجموع» تدل على عملية:","o":["الجمع","الطرح","الضرب","القسمة"],"a":0,"why":"كلمة «المجموع» تدل على الجمع، فمجموع عددين هو ناتج جمعهما. تذكّر: المجموع وزاد وأكبر من (جمع)، والفرق وأقل من (طرح)، وأمثال (ضرب)، وناتج القسمة (÷)، ويساوي (=).","ow":["","الطرح تدل عليه كلمة «الفرق».","الضرب تدل عليه كلمة «أمثال» أو «حاصل ضرب».","القسمة تدل عليها كلمة «ناتج قسمة»."]},
  {"q":"كلمة «الفرق» تدل على عملية:","o":["الجمع","الضرب","القسمة","الطرح"],"a":3,"why":"كلمة «الفرق» تدل على الطرح، فالفرق بين عددين هو ناتج طرحهما. تذكّر: المجموع وزاد وأكبر من (جمع)، والفرق وأقل من (طرح)، وأمثال (ضرب)، وناتج القسمة (÷)، ويساوي (=).","ow":["الجمع تدل عليه كلمة «المجموع».","الضرب تدل عليه كلمة «أمثال».","القسمة تدل عليها كلمة «ناتج قسمة».",""]},
  {"q":"كلمة «أمثال» تدل على عملية:","o":["الجمع","الطرح","الضرب","القسمة"],"a":2,"why":"كلمة «أمثال» تدل على الضرب. ثلاثة أمثال عدد = 3 × العدد. تذكّر: المجموع وزاد وأكبر من (جمع)، والفرق وأقل من (طرح)، وأمثال (ضرب)، وناتج القسمة (÷)، ويساوي (=).","ow":["الجمع تدل عليه «المجموع» أو «زاد».","الطرح تدل عليه «الفرق» أو «أقل من».","","القسمة تدل عليها «ناتج قسمة»."]},
  {"q":"عبارة «ناتج قسمة» تدل على عملية:","o":["الجمع","القسمة","الطرح","الضرب"],"a":1,"why":"عبارة «ناتج قسمة» تدل على عملية القسمة (÷). تذكّر: المجموع وزاد وأكبر من (جمع)، والفرق وأقل من (طرح)، وأمثال (ضرب)، وناتج القسمة (÷)، ويساوي (=).","ow":["الجمع تدل عليه «المجموع».","","الطرح تدل عليه «الفرق».","الضرب تدل عليه «أمثال»."]},
  {"q":"اكتب بعبارة جبرية: أكبر من العدد س بمقدار 9","o":["س + 9","س − 9","9 س","س ÷ 9"],"a":0,"why":"عبارة «أكبر من العدد س بمقدار 9» تعني أننا نزيد 9 على العدد، فهي جمع: س + 9. تذكّر: المجموع وزاد وأكبر من (جمع)، والفرق وأقل من (طرح)، وأمثال (ضرب)، وناتج القسمة (÷)، ويساوي (=).","ow":["","س − 9 تعني أقل من س بمقدار 9.","9س تعني تسعة أمثال العدد س.","س ÷ 9 تعني ناتج قسمة س على 9."]},
  {"q":"اكتب بعبارة جبرية: أقل من العدد ع بمقدار 4","o":["ع + 4","4 − ع","4 ع","ع − 4"],"a":3,"why":"عبارة «أقل من العدد ع بمقدار 4» تعني أننا ننقص 4 من العدد، فنكتب ع − 4 (ونبدأ بالعدد ع).","ow":["ع + 4 تعني أكبر من ع بمقدار 4.","4 − ع تعكس الترتيب، فهي تعني الفرق بين 4 و ع.","4ع تعني أربعة أمثال العدد ع.",""]},
  {"q":"اكتب بعبارة جبرية: ثلاثة أمثال العدد ن","o":["ن + 3","ن − 3","3 ن","ن ÷ 3"],"a":2,"why":"«ثلاثة أمثال العدد ن» تعني ضرب العدد في 3، فنكتب 3ن. تذكّر: المجموع وزاد وأكبر من (جمع)، والفرق وأقل من (طرح)، وأمثال (ضرب)، وناتج القسمة (÷)، ويساوي (=).","ow":["ن + 3 تعني أكبر من ن بمقدار 3.","ن − 3 تعني أقل من ن بمقدار 3.","","ن ÷ 3 تعني ناتج قسمة ن على 3."]},
  {"q":"اكتب بعبارة جبرية: مجموع العدد ك و 10","o":["ك − 10","ك + 10","10 ك","ك ÷ 10"],"a":1,"why":"«مجموع العدد ك و 10» يعني جمع ك و 10، فنكتب ك + 10. تذكّر: المجموع وزاد وأكبر من (جمع)، والفرق وأقل من (طرح)، وأمثال (ضرب)، وناتج القسمة (÷)، ويساوي (=).","ow":["ك − 10 تعني الفرق بينهما.","","10ك تعني عشرة أمثال ك.","ك ÷ 10 تعني ناتج قسمة ك على 10."]},
  {"q":"اكتب بعبارة جبرية: ناتج قسمة العدد ص على 3","o":["ص ÷ 3","3 ÷ ص","ص − 3","3 ص"],"a":0,"why":"في «ناتج قسمة ص على 3» العدد ص هو المقسوم (يُكتب أولًا)، فنكتب ص ÷ 3. تذكّر: المجموع وزاد وأكبر من (جمع)، والفرق وأقل من (طرح)، وأمثال (ضرب)، وناتج القسمة (÷)، ويساوي (=).","ow":["","3 ÷ ص تعني قسمة 3 على ص وهذا عكس المطلوب.","ص − 3 تعني الفرق بين ص و 3.","3ص تعني ثلاثة أمثال ص."]},
  {"q":"اكتب بمعادلة: أكبر من العدد س بمقدار 4 يساوي 11","o":["س − 4 = 11","4 س = 11","س + 11 = 4","س + 4 = 11"],"a":3,"why":"«أكبر من العدد س بمقدار 4» تعني س + 4، و «يساوي 11» تعني = 11. فالمعادلة س + 4 = 11 (والحل س = 7).","ow":["س − 4 = 11 تعني أقل من س بمقدار 4.","4س = 11 تعني أربعة أمثال س.","س + 11 = 4 تعكس العددين 4 و 11.",""]},
  {"q":"اكتب بمعادلة: أربعة أمثال العدد ع يساوي 20","o":["ع + 4 = 20","ع − 4 = 20","4 ع = 20","ع ÷ 4 = 20"],"a":2,"why":"«أربعة أمثال العدد ع» تعني 4 × ع = 4ع، و «يساوي 20» تعني = 20. فالمعادلة 4ع = 20.","ow":["ع + 4 = 20 تعني أكبر من ع بمقدار 4.","ع − 4 = 20 تعني أقل من ع بمقدار 4.","","ع ÷ 4 = 20 تعني ناتج قسمة ع على 4."]},
  {"q":"اكتب بمعادلة: أقل من العدد ن بمقدار 3 يساوي 8","o":["ن + 3 = 8","ن − 3 = 8","3 ن = 8","3 − ن = 8"],"a":1,"why":"«أقل من العدد ن بمقدار 3» تعني ن − 3، و «يساوي 8» تعني = 8. فالمعادلة ن − 3 = 8.","ow":["ن + 3 = 8 تعني أكبر من ن بمقدار 3.","","3ن = 8 تعني ثلاثة أمثال ن.","3 − ن = 8 تعكس الترتيب (ن يجب أن تُكتب أولًا)."]},
  {"q":"كان مع نواف س ريالًا، أنفق 15 ريالًا فبقي معه 25 ريالًا. أي معادلة تمثل ذلك؟","o":["س − 15 = 25","س + 15 = 25","15 س = 25","س ÷ 15 = 25"],"a":0,"why":"مع نواف س ريالًا، أنفق 15 (طرح) فبقي 25، فالمعادلة س − 15 = 25 (والحل س = 40). تذكّر: المجموع وزاد وأكبر من (جمع)، والفرق وأقل من (طرح)، وأمثال (ضرب)، وناتج القسمة (÷)، ويساوي (=).","ow":["","س + 15 = 25 تعني أنه أخذ 15 لا أنفقها.","15س = 25 تعني ضربًا والمسألة فيها إنفاق.","س ÷ 15 = 25 تعني قسمة والمسألة فيها إنفاق."]},
  {"q":"سعر القلم 3 ريالات. اشترى ماجد ع قلمًا بمبلغ 21 ريالًا. أي معادلة تمثل ذلك؟","o":["ع + 3 = 21","ع − 3 = 21","3 ع = 7","3 ع = 21"],"a":3,"why":"ثمن الأقلام = سعر القلم × عددها، فـ 3 × ع = 21، أي 3ع = 21 (والحل ع = 7). تذكّر: المجموع وزاد وأكبر من (جمع)، والفرق وأقل من (طرح)، وأمثال (ضرب)، وناتج القسمة (÷)، ويساوي (=).","ow":["ع + 3 = 21 تعني جمعًا والمسألة فيها شراء بعدد وسعر.","ع − 3 = 21 تعني طرحًا والمسألة فيها شراء بعدد وسعر.","3ع = 7 تعطي المبلغ 7 بدل 21.",""]},
  {"q":"عدد الطلاب ن، وبعد انضمام 6 طلاب صار 40. أي معادلة تمثل ذلك؟","o":["ن − 6 = 40","6 ن = 40","ن + 6 = 40","ن + 40 = 6"],"a":2,"why":"عدد الطلاب ن، وانضم 6 (زيادة) فصار 40، فالمعادلة ن + 6 = 40 (والحل ن = 34). تذكّر: المجموع وزاد وأكبر من (جمع)، والفرق وأقل من (طرح)، وأمثال (ضرب)، وناتج القسمة (÷)، ويساوي (=).","ow":["ن − 6 = 40 تعني أن العدد نقص لا زاد.","6ن = 40 تعني ضربًا والمسألة فيها انضمام.","","ن + 40 = 6 تعكس العددين 6 و 40."]},
  {"q":"عبارة «زاد بمقدار» تدل على الجمع.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: «زاد بمقدار» تعني أن نضيف المقدار، فهي جمع. تذكّر: المجموع وزاد وأكبر من (جمع)، والفرق وأقل من (طرح)، وأمثال (ضرب)، وناتج القسمة (÷)، ويساوي (=).","ow":["","«خطأ» غير صحيحة؛ الزيادة تعني الجمع."]},
  {"q":"تُكتب «أقل من العدد س بمقدار 6» بالصورة 6 − س.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: «أقل من العدد س بمقدار 6» تُكتب س − 6 (نبدأ بالعدد س)، أما 6 − س فهي الفرق بين 6 و س.","ow":["«صح» تعني أنها تكتب 6 − س، لكن الترتيب يبدأ بالعدد س.",""]},
  {"q":"المعادلة 5 ع = 40 تمثل: خمسة أمثال العدد ع تساوي 40.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: 5ع تعني 5 × ع، أي خمسة أمثال ع، والمعادلة 5ع = 40 تعني أنها تساوي 40 (ع = 8).","ow":["","«خطأ» غير صحيحة؛ «أمثال» تعني ضربًا."]},
  {"q":"تُكتب «ناتج قسمة س على 4» بالصورة 4 ÷ س.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: «ناتج قسمة س على 4» تعني س ÷ 4 (س هو المقسوم يُكتب أولًا) وليس 4 ÷ س.","ow":["«صح» تعني أنها 4 ÷ س، لكن س هو المقسوم.",""]},
  {"q":"كلمة «يساوي» تعني أننا نكتب معادلة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: كلمة «يساوي» تُترجم إلى إشارة التساوي (=)، فنكتب معادلة. تذكّر: المجموع وزاد وأكبر من (جمع)، والفرق وأقل من (طرح)، وأمثال (ضرب)، وناتج القسمة (÷)، ويساوي (=).","ow":["","«خطأ» غير صحيحة؛ «يساوي» تعني =."]}
];
