  {"q":"هل 2/3 و 4/6 تشكلان تناسبًا؟","o":["لا","لا يمكن الحكم","نعم","فقط إذا تساوى المقامان"],"a":2,"why":"نستعمل الضرب التبادلي: 2 × 6 = 12 و 3 × 4 = 12، متساويان فهما تناسب. أو 4/6 = 2/3 بقسمة الحدين على 2.","ow":["«لا» غير صحيحة؛ الحاصلان متساويان.","يمكن الحكم بالضرب التبادلي.","","التناسب لا يشترط تساوي المقامين."]},
  {"q":"هل 3/5 و 6/11 تشكلان تناسبًا؟","o":["نعم","لا","لا يمكن الحكم","فقط إذا تساوى البسطان"],"a":1,"why":"الضرب التبادلي: 3 × 11 = 33 و 5 × 6 = 30، غير متساويين، فلا تشكلان تناسبًا. تذكّر: التناسب تساوي نسبتين، ونحل المجهول بالضرب التبادلي: في أ/ب = ج/د يكون أ × د = ب × ج.","ow":["«نعم» غير صحيحة؛ 33 لا يساوي 30.","","يمكن الحكم بالضرب التبادلي.","التناسب لا يشترط تساوي البسطين."]},
  {"q":"حل التناسب: س/4 = 9/12","o":["س = 3","س = 27","س = 12","س = 1/3"],"a":0,"why":"نستعمل الضرب التبادلي: س × 12 = 4 × 9. فـ 12س = 36، ثم نقسم على 12: س = 36 ÷ 12 = 3. للتحقق: 3 × 12 = 4 × 9.","ow":["","27 لا تحقق التناسب: بالتعويض يكون الحاصلان 324 و 36 وهما غير متساويين.","12 لا تحقق التناسب: بالتعويض يكون الحاصلان 144 و 36 وهما غير متساويين.","1/3 لا تحقق التناسب: بالتعويض يكون الحاصلان 4 و 36 وهما غير متساويين."]},
  {"q":"حل التناسب: 5/10 = س/8","o":["س = 16","س = 2","س = 40","س = 4"],"a":3,"why":"نستعمل الضرب التبادلي: 5 × 8 = 10 × س. فـ 10س = 40، ثم نقسم على 10: س = 40 ÷ 10 = 4. للتحقق: 5 × 8 = 10 × 4.","ow":["16 لا تحقق التناسب: بالتعويض يكون الحاصلان 40 و 160 وهما غير متساويين.","2 لا تحقق التناسب: بالتعويض يكون الحاصلان 40 و 20 وهما غير متساويين.","40 لا تحقق التناسب: بالتعويض يكون الحاصلان 40 و 400 وهما غير متساويين.",""]},
  {"q":"حل التناسب: 6/9 = 8/س","o":["س = 6","س = 48","س = 12","س = 4"],"a":2,"why":"نستعمل الضرب التبادلي: 6 × س = 9 × 8. فـ 6س = 72، ثم نقسم على 6: س = 72 ÷ 6 = 12. للتحقق: 6 × 12 = 9 × 8.","ow":["6 لا تحقق التناسب: بالتعويض يكون الحاصلان 36 و 72 وهما غير متساويين.","48 لا تحقق التناسب: بالتعويض يكون الحاصلان 288 و 72 وهما غير متساويين.","","4 لا تحقق التناسب: بالتعويض يكون الحاصلان 24 و 72 وهما غير متساويين."]},
  {"q":"حل التناسب: 3/س = 12/20","o":["س = 4","س = 5","س = 80","س = 36"],"a":1,"why":"نستعمل الضرب التبادلي: 3 × 20 = س × 12. فـ 12س = 60، ثم نقسم على 12: س = 60 ÷ 12 = 5. للتحقق: 3 × 20 = 5 × 12.","ow":["4 لا تحقق التناسب: بالتعويض يكون الحاصلان 60 و 48 وهما غير متساويين.","","80 لا تحقق التناسب: بالتعويض يكون الحاصلان 60 و 960 وهما غير متساويين.","36 لا تحقق التناسب: بالتعويض يكون الحاصلان 60 و 432 وهما غير متساويين."]},
  {"q":"في التناسب أ/ب = ج/د يتحقق الضرب التبادلي:","o":["أ × د = ب × ج","أ × ج = ب × د","أ + د = ب + ج","أ × ب = ج × د"],"a":0,"why":"في التناسب أ/ب = ج/د يتحقق الضرب التبادلي: أ × د = ب × ج (البسط الأول في المقام الثاني يساوي المقام الأول في البسط الثاني).","ow":["","أ × ج = ب × د ضرب البسطين مقابل ضرب المقامين وهذا غير صحيح.","الجمع لا يمثل الضرب التبادلي.","أ × ب = ج × د ضرب كل نسبة في نفسها وهذا غير صحيح."]},
  {"q":"ثمن 4 كتب 20 ريالًا. كم ثمن 10 كتب بالمعدل نفسه؟","o":["30 ريالًا","80 ريالًا","200 ريال","50 ريالًا"],"a":3,"why":"ثمن 4 كتب 20 ريالًا: 4/20 = 10/ث. الضرب التبادلي: 4 × ث = 20 × 10 = 200، فـ ث = 200 ÷ 4 = 50 ريالًا. (ثمن الكتاب 5 ريالات: 10 × 5 = 50).","ow":["30 ريالًا يعطي ثمن الكتاب 3 ريالات وليس 5.","80 ريالًا يعطي ثمن الكتاب 8 ريالات وليس 5.","200 ريال هو حاصل الضرب 20 × 10 قبل القسمة على 4.",""]},
  {"q":"تقطع سيارة 150 كلم في ساعتين. كم تقطع في 6 ساعات بالمعدل نفسه؟","o":["300 كلم","900 كلم","450 كلم","156 كلم"],"a":2,"why":"150/2 = ك/6. الضرب التبادلي: 2 × ك = 150 × 6 = 900، فـ ك = 900 ÷ 2 = 450 كلم. (السرعة 75 كلم/ساعة: 75 × 6 = 450).","ow":["300 كلم هي المسافة في 4 ساعات (75 × 4).","900 كلم هو حاصل الضرب 150 × 6 قبل القسمة على 2.","","156 كلم ناتج 150 + 6 أي جمعنا بدل التناسب."]},
  {"q":"نسبة السكر إلى الماء 1 : 4. كم جرامًا من السكر في 20 جم ماء؟","o":["4 جم","5 جم","16 جم","80 جم"],"a":1,"why":"نسبة السكر إلى الماء 1 : 4، فـ 1/4 = س/20. الضرب التبادلي: 4 × س = 1 × 20 = 20، فـ س = 20 ÷ 4 = 5 جم.","ow":["4 جم تعني نسبة 4 : 20 أي 1 : 5 وليست 1 : 4.","","16 جم تعني نسبة 16 : 20 وهي غير 1 : 4.","80 جم هو 20 × 4 أي ضربنا بدل القسمة."]},
  {"q":"ركض عداء 3 دورات في 15 ثانية و 5 دورات في 25 ثانية. هل الدورات تتناسب مع الزمن؟","o":["نعم","لا","لا يمكن الحكم","فقط في الدورات"],"a":0,"why":"الدورات إلى الزمن: 3/15 و 5/25. الضرب التبادلي: 3 × 25 = 75 و 15 × 5 = 75، متساويان، فالنسبتان تشكلان تناسبًا (كل منهما = 1/5).","ow":["","«لا» غير صحيحة؛ الحاصلان متساويان.","يمكن الحكم بالضرب التبادلي.","التناسب يطبق على الدورات والزمن معًا وليس الدورات فقط."]},
  {"q":"حل التناسب: 6/8 = 9/س","o":["س = 6","س = 72","س = 10","س = 12"],"a":3,"why":"نستعمل الضرب التبادلي: 6 × س = 8 × 9. فـ 6س = 72، ثم نقسم على 6: س = 72 ÷ 6 = 12. للتحقق: 6 × 12 = 8 × 9.","ow":["6 لا تحقق التناسب: بالتعويض يكون الحاصلان 36 و 72 وهما غير متساويين.","72 لا تحقق التناسب: بالتعويض يكون الحاصلان 432 و 72 وهما غير متساويين.","10 لا تحقق التناسب: بالتعويض يكون الحاصلان 60 و 72 وهما غير متساويين.",""]},
  {"q":"حل التناسب: 7/س = 21/9","o":["س = 27","س = 7","س = 3","س = 63"],"a":2,"why":"نستعمل الضرب التبادلي: 7 × 9 = س × 21. فـ 21س = 63، ثم نقسم على 21: س = 63 ÷ 21 = 3. للتحقق: 7 × 9 = 3 × 21.","ow":["27 لا تحقق التناسب: بالتعويض يكون الحاصلان 63 و 567 وهما غير متساويين.","7 لا تحقق التناسب: بالتعويض يكون الحاصلان 63 و 147 وهما غير متساويين.","","63 لا تحقق التناسب: بالتعويض يكون الحاصلان 63 و 1323 وهما غير متساويين."]},
  {"q":"حل التناسب: 2/5 = س/35","o":["س = 7","س = 14","س = 70","س = 2"],"a":1,"why":"نستعمل الضرب التبادلي: 2 × 35 = 5 × س. فـ 5س = 70، ثم نقسم على 5: س = 70 ÷ 5 = 14. للتحقق: 2 × 35 = 5 × 14.","ow":["7 لا تحقق التناسب: بالتعويض يكون الحاصلان 70 و 35 وهما غير متساويين.","","70 لا تحقق التناسب: بالتعويض يكون الحاصلان 70 و 350 وهما غير متساويين.","2 لا تحقق التناسب: بالتعويض يكون الحاصلان 70 و 10 وهما غير متساويين."]},
  {"q":"ثمن 3 أقلام 6 ريالات. كم ثمن 7 أقلام بالسعر نفسه؟","o":["14 ريالًا","13 ريالًا","18 ريالًا","42 ريالًا"],"a":0,"why":"ثمن 3 أقلام 6 ريالات: 3/6 = 7/ث. الضرب التبادلي: 3 × ث = 6 × 7 = 42، فـ ث = 42 ÷ 3 = 14 ريالًا. (القلم بـ 2 ريال: 7 × 2 = 14).","ow":["","13 ريالًا غير صحيح؛ القلم بـ 2 ريال فتكون 7 أقلام بـ 14.","18 ريالًا يعني أن القلم بـ 2.57 ريال تقريبًا وهو لا يطابق.","42 ريالًا هو حاصل الضرب 6 × 7 قبل القسمة على 3."]},
  {"q":"النسبتان 2/3 و 6/9 تشكلان تناسبًا.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: الضرب التبادلي 2 × 9 = 18 و 3 × 6 = 18 متساويان، أو 6/9 = 2/3 بالتبسيط.","ow":["","«خطأ» غير صحيحة؛ النسبتان متساويتان."]},
  {"q":"النسبتان 1/2 و 2/5 تشكلان تناسبًا.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: الضرب التبادلي 1 × 5 = 5 و 2 × 2 = 4، غير متساويين فلا تشكلان تناسبًا.","ow":["«صح» تعني أنهما تناسب، لكن 5 لا يساوي 4.",""]},
  {"q":"في التناسب أ/ب = ج/د يكون أ × د = ب × ج.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: هذا هو الضرب التبادلي: في أ/ب = ج/د يكون أ × د = ب × ج. تذكّر: التناسب تساوي نسبتين، ونحل المجهول بالضرب التبادلي: في أ/ب = ج/د يكون أ × د = ب × ج.","ow":["","«خطأ» غير صحيحة؛ هذه خاصية التناسب."]},
  {"q":"حل التناسب س/6 = 2/3 هو س = 4.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: س/6 = 2/3 فالضرب التبادلي 3 × س = 6 × 2 = 12، فـ س = 4. التحقق: 4/6 = 2/3.","ow":["","«خطأ» غير صحيحة؛ س = 4 فعلًا."]},
  {"q":"حل التناسب 3/س = 1/4 هو س = 3.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: 3/س = 1/4 فالضرب التبادلي 1 × س = 3 × 4 = 12، فـ س = 12 وليس 3. التحقق: 3/12 = 1/4.","ow":["«صح» تعني أن س = 3، لكن 3/3 = 1 وليس 1/4.",""]}
