  {"q":"اكتب 40٪ على صورة كسر في أبسط صورة","o":["2/5","4/5","1/4","40/10"],"a":0,"why":"النسبة المئوية مقامها 100، فـ 40٪ = 40/100. نقسم البسط والمقام على القاسم المشترك الأكبر 20: 40÷20 = 2 و 100÷20 = 5، فالكسر 2/5.","ow":["","4/5 تساوي 80٪ وليست 40٪؛ الكسر الصحيح 2/5.","1/4 تساوي 25٪ وليست 40٪؛ الكسر الصحيح 2/5.","40/10 تساوي 400٪ وليست 40٪؛ الكسر الصحيح 2/5."]},
  {"q":"اكتب 20٪ على صورة كسر في أبسط صورة","o":["2/5","1/2","20/10","1/5"],"a":3,"why":"النسبة المئوية مقامها 100، فـ 20٪ = 20/100. نقسم البسط والمقام على القاسم المشترك الأكبر 20: 20÷20 = 1 و 100÷20 = 5، فالكسر 1/5.","ow":["2/5 تساوي 40٪ وليست 20٪؛ الكسر الصحيح 1/5.","1/2 تساوي 50٪ وليست 20٪؛ الكسر الصحيح 1/5.","20/10 تساوي 200٪ وليست 20٪؛ الكسر الصحيح 1/5.",""]},
  {"q":"اكتب 10٪ على صورة كسر في أبسط صورة","o":["1/100","1/5","1/10","10/10"],"a":2,"why":"النسبة المئوية مقامها 100، فـ 10٪ = 10/100. نقسم البسط والمقام على القاسم المشترك الأكبر 10: 10÷10 = 1 و 100÷10 = 10، فالكسر 1/10.","ow":["1/100 تساوي 1٪ وليست 10٪؛ الكسر الصحيح 1/10.","1/5 تساوي 20٪ وليست 10٪؛ الكسر الصحيح 1/10.","","10/10 تساوي 100٪ وليست 10٪؛ الكسر الصحيح 1/10."]},
  {"q":"اكتب 125٪ على صورة كسر في أبسط صورة","o":["4/5","5/4","1/4","12/5"],"a":1,"why":"النسبة المئوية مقامها 100، فـ 125٪ = 125/100. نقسم البسط والمقام على القاسم المشترك الأكبر 25: 125÷25 = 5 و 100÷25 = 4، فالكسر 5/4 (ويساوي 1 1/4).","ow":["4/5 تساوي 80٪ وليست 125٪؛ الكسر الصحيح 5/4.","","1/4 تساوي 25٪ وليست 125٪؛ الكسر الصحيح 5/4.","12/5 تساوي 240٪ وليست 125٪؛ الكسر الصحيح 5/4."]},
  {"q":"اكتب 5٪ على صورة كسر في أبسط صورة","o":["1/20","1/5","5/10","1/50"],"a":0,"why":"النسبة المئوية مقامها 100، فـ 5٪ = 5/100. نقسم البسط والمقام على القاسم المشترك الأكبر 5: 5÷5 = 1 و 100÷5 = 20، فالكسر 1/20.","ow":["","1/5 تساوي 20٪ وليست 5٪؛ الكسر الصحيح 1/20.","5/10 تساوي 50٪ وليست 5٪؛ الكسر الصحيح 1/20.","1/50 تساوي 2٪ وليست 5٪؛ الكسر الصحيح 1/20."]},
  {"q":"اكتب 35٪ على صورة كسر في أبسط صورة","o":["3/5","35/10","7/10","7/20"],"a":3,"why":"النسبة المئوية مقامها 100، فـ 35٪ = 35/100. نقسم البسط والمقام على القاسم المشترك الأكبر 5: 35÷5 = 7 و 100÷5 = 20، فالكسر 7/20.","ow":["3/5 تساوي 60٪ وليست 35٪؛ الكسر الصحيح 7/20.","35/10 تساوي 350٪ وليست 35٪؛ الكسر الصحيح 7/20.","7/10 تساوي 70٪ وليست 35٪؛ الكسر الصحيح 7/20.",""]},
  {"q":"اكتب 1/2 على صورة نسبة مئوية","o":["12٪","20٪","50٪","5٪"],"a":2,"why":"نكتب كسرًا مقامه 100: نضرب البسط والمقام في 50: 1×50 = 50 و 2×50 = 100، فالكسر 50/100 = 50٪.","ow":["12٪ تساوي 3/25 من الكل وليست 1/2؛ الصحيح 50٪.","20٪ تساوي 1/5 من الكل وليست 1/2؛ الصحيح 50٪.","","5٪ تساوي 1/20 من الكل وليست 1/2؛ الصحيح 50٪."]},
  {"q":"اكتب 1/4 على صورة نسبة مئوية","o":["14٪","25٪","40٪","4٪"],"a":1,"why":"نكتب كسرًا مقامه 100: نضرب البسط والمقام في 25: 1×25 = 25 و 4×25 = 100، فالكسر 25/100 = 25٪.","ow":["14٪ تساوي 7/50 من الكل وليست 1/4؛ الصحيح 25٪.","","40٪ تساوي 2/5 من الكل وليست 1/4؛ الصحيح 25٪.","4٪ تساوي 1/25 من الكل وليست 1/4؛ الصحيح 25٪."]},
  {"q":"اكتب 7/10 على صورة نسبة مئوية","o":["70٪","7٪","710٪","17٪"],"a":0,"why":"نكتب كسرًا مقامه 100: نضرب البسط والمقام في 10: 7×10 = 70 و 10×10 = 100، فالكسر 70/100 = 70٪.","ow":["","7٪ تساوي 7/100 من الكل وليست 7/10؛ الصحيح 70٪.","710٪ تساوي 71/10 من الكل وليست 7/10؛ الصحيح 70٪.","17٪ تساوي 17/100 من الكل وليست 7/10؛ الصحيح 70٪."]},
  {"q":"اكتب 2/5 على صورة نسبة مئوية","o":["25٪","52٪","4٪","40٪"],"a":3,"why":"نكتب كسرًا مقامه 100: نضرب البسط والمقام في 20: 2×20 = 40 و 5×20 = 100، فالكسر 40/100 = 40٪.","ow":["25٪ تساوي 1/4 من الكل وليست 2/5؛ الصحيح 40٪.","52٪ تساوي 13/25 من الكل وليست 2/5؛ الصحيح 40٪.","4٪ تساوي 1/25 من الكل وليست 2/5؛ الصحيح 40٪.",""]},
  {"q":"اكتب 9/20 على صورة نسبة مئوية","o":["9٪","29٪","45٪","90٪"],"a":2,"why":"نكتب كسرًا مقامه 100: نضرب البسط والمقام في 5: 9×5 = 45 و 20×5 = 100، فالكسر 45/100 = 45٪.","ow":["9٪ تساوي 9/100 من الكل وليست 9/20؛ الصحيح 45٪.","29٪ تساوي 29/100 من الكل وليست 9/20؛ الصحيح 45٪.","","90٪ تساوي 9/10 من الكل وليست 9/20؛ الصحيح 45٪."]},
  {"q":"اكتب 3/8 على صورة نسبة مئوية","o":["38٪","37.5٪","3.8٪","83٪"],"a":1,"why":"نقسم 3 ÷ 8 = 0.375 ثم نضرب في 100: 0.375 × 100 = 37.5٪. تذكّر: النسبة المئوية كسر مقامه 100، فنحوّل بين الكسر والنسبة المئوية بتوحيد المقام أو بالقسمة ثم الضرب في 100.","ow":["38٪ تساوي 19/50 من الكل وليست 3/8؛ الصحيح 37.5٪.","","3.8٪ تساوي 19/500 من الكل وليست 3/8؛ الصحيح 37.5٪.","83٪ تساوي 83/100 من الكل وليست 3/8؛ الصحيح 37.5٪."]},
  {"q":"اكتب 1/8 على صورة نسبة مئوية","o":["12.5٪","18٪","1.25٪","8٪"],"a":0,"why":"نقسم 1 ÷ 8 = 0.125 ثم نضرب في 100: 0.125 × 100 = 12.5٪. تذكّر: النسبة المئوية كسر مقامه 100، فنحوّل بين الكسر والنسبة المئوية بتوحيد المقام أو بالقسمة ثم الضرب في 100.","ow":["","18٪ تساوي 9/50 من الكل وليست 1/8؛ الصحيح 12.5٪.","1.25٪ تساوي 1/80 من الكل وليست 1/8؛ الصحيح 12.5٪.","8٪ تساوي 2/25 من الكل وليست 1/8؛ الصحيح 12.5٪."]},
  {"q":"ما النسبة المئوية؟","o":["نسبة مقامها 10","نسبة بسطها 100","عدد صحيح فقط","نسبة مقامها 100"],"a":3,"why":"النسبة المئوية هي نسبة مقامها 100، مثل 25٪ = 25/100. تذكّر: النسبة المئوية كسر مقامه 100، فنحوّل بين الكسر والنسبة المئوية بتوحيد المقام أو بالقسمة ثم الضرب في 100.","ow":["المقام 10 يخص الكسور العشرية لا النسبة المئوية.","ليس البسط هو 100 بل المقام.","النسبة المئوية قد تكون كسرًا أو عددًا عشريًا وليست عددًا صحيحًا فقط.",""]},
  {"q":"اكتب 33 1/3 ٪ على صورة كسر","o":["1/33","3/10","1/3","1/30"],"a":2,"why":"33 1/3 ٪ = (100/3)/100 = 100/300 = 1/3. فهذه النسبة تعادل ثلث الكل. تذكّر: النسبة المئوية كسر مقامه 100، فنحوّل بين الكسر والنسبة المئوية بتوحيد المقام أو بالقسمة ثم الضرب في 100.","ow":["1/33 غير صحيح؛ المقام 100/ (100/3) = 3 وليس 33.","3/10 تساوي 30٪ فقط.","","1/30 تساوي 3.33٪ فقط."]},
  {"q":"50٪ = 1/2","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: 50٪ = 50/100 = 1/2 بقسمة البسط والمقام على 50. تذكّر: النسبة المئوية كسر مقامه 100، فنحوّل بين الكسر والنسبة المئوية بتوحيد المقام أو بالقسمة ثم الضرب في 100.","ow":["","«خطأ» غير صحيحة؛ 50٪ نصف الكل."]},
  {"q":"25٪ = 1/2","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: 25٪ = 25/100 = 1/4 وليس 1/2. أما 1/2 فتساوي 50٪. تذكّر: النسبة المئوية كسر مقامه 100، فنحوّل بين الكسر والنسبة المئوية بتوحيد المقام أو بالقسمة ثم الضرب في 100.","ow":["«صح» تعني أن 25٪ نصف، لكنها ربع.",""]},
  {"q":"3/4 = 75٪","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: 3/4 = 75/100 (ضربنا البسط والمقام في 25) = 75٪. تذكّر: النسبة المئوية كسر مقامه 100، فنحوّل بين الكسر والنسبة المئوية بتوحيد المقام أو بالقسمة ثم الضرب في 100.","ow":["","«خطأ» غير صحيحة؛ 3/4 تساوي 75٪."]},
  {"q":"1/5 = 50٪","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ: 1/5 = 20/100 = 20٪ وليس 50٪. أما 50٪ فتساوي 1/2. تذكّر: النسبة المئوية كسر مقامه 100، فنحوّل بين الكسر والنسبة المئوية بتوحيد المقام أو بالقسمة ثم الضرب في 100.","ow":["«صح» تعني أن 1/5 = 50٪، لكنها 20٪.",""]},
  {"q":"100٪ = 1","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة: 100٪ = 100/100 = 1 أي الكل كاملًا. تذكّر: النسبة المئوية كسر مقامه 100، فنحوّل بين الكسر والنسبة المئوية بتوحيد المقام أو بالقسمة ثم الضرب في 100.","ow":["","«خطأ» غير صحيحة؛ 100٪ = 1."]}
